begin;
    with j as (select * from jsonb_to_recordset($law7v009$[{"code_id":"GK_RF","article_number":"315","version_date":"1994-11-30","article_text":"Должник вправе исполнить обязательство до срока, если иное не предусмотрено законом, иными правовыми актами или условиями обязательства либо не вытекает из его существа. Однако досрочное исполнение обязательств, связанных с осуществлением его сторонами предпринимательской деятельности, допускается только в случаях, когда возможность исполнить обязательство до срока предусмотрена законом, иными правовыми актами или условиями обязательства либо вытекает из обычаев или существа обязательства. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 315. Досрочное исполнение обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f571fad45c5f302b073dbe37f5edc9c4fe33346efae5878e997248ce3821bea6"},{"code_id":"GK_RF","article_number":"316","version_date":"1994-11-30","article_text":"1. Если место исполнения обязательства не определено законом, иными правовыми актами или договором, не явст\n\nвует из обычаев либо существа обязательства, исполнение должно быть произведено:\n\nпо обязательству передать земельный участок, здание, сооружение или другое недвижимое имущество - в месте нахождения такого имущества;\n\nпо обязательству передать товар или иное имущество, предусматривающему его перевозку, - в месте сдачи имущества первому перевозчику для доставки его кредитору;\n\nпо другим обязательствам предпринимателя передать товар или иное имущество - в месте изготовления или хранения имущества, если это место было известно кредитору в момент возникновения обязательства;\n\nпо денежному обязательству об уплате наличных денег - в месте жительства кредитора в момент возникновения обязательства или, если кредитором является юридическое лицо, в месте его нахождения в момент возникновения обязательства;\n\nпо денежному обязательству об уплате безналичных денежных средств - в месте нахождения банка (его филиала, подразделения), обслуживающего кредитора, если иное не предусмотрено законом;\n\nпо всем другим обязательствам - в месте жительства должника или, если должником является юридическое лицо, в месте его нахождения.\n\n2. Если после возникновения обязательства место его исполнения изменилось, в частности изменилось место жительство должника или кредитора, сторона, от которой зависело такое изменение, обязана возместить другой стороне дополнительные издержки, а также принимает на себя дополнительные риски, связанные с изменением места исполнения обязательства.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 316. Место исполнения обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0819333676a055aa82721661ba6f2aa0dca7c21fa4997d1362d5c44922a94415"},{"code_id":"GK_RF","article_number":"317","version_date":"1994-11-30","article_text":"1. Денежные обязательства должны быть выражены в рублях (статья 140).\n\n2. В денежном обязательстве может быть предусмотрено, что оно подлежит оплате в рублях в сумме, эквивалентной определенной сумме в иностранной валюте или в условных денежных единицах (экю, \"специальных правах заимствования\" и др.). В этом случае подлежащая уплате в рублях сумма определяется по официальному курсу соответствующей валюты или условных денежных единиц на день платежа, если иной курс или иная дата его определения не установлены законом или соглашением сторон.\n\n3. Использование иностранной валюты, а также платежных документов в иностранной валюте при осуществлении расчетов на территории Российской Федерации по обязательствам допускается в случаях, в порядке и на условиях, определенных законом или в установленном им порядке.","article_title":"Статья 317. Валюта денежных обязательств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"524d0321ebaba840842da5293ee9206bda53cce209dba71dbdec7b16ff36e72d"},{"code_id":"GK_RF","article_number":"317.1","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 317.1. Проценты по денежному обязательству","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64fabe95d849588f806cfc714ea30e5d29cf7de23abe3a20e6c305cde4c395fa"},{"code_id":"GK_RF","article_number":"318","version_date":"1994-11-30","article_text":"Если иное не предусмотрено законом, сумма, выплачиваемая по денежному обязательству непосредственно на содержание гражданина, в том числе в возмещение вреда, причиненного жизни или здоровью, либо по договору пожизненного содержания, увеличивается пропорционально повышению установленной в соответствии с законом величины прожиточного минимума.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 318. Увеличение сумм, выплачиваемых на содержание гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"087607f1ecd296f012d2ff89081b5f882ea15f52a4b25dca8c820c7e6f473271"},{"code_id":"GK_RF","article_number":"319","version_date":"1994-11-30","article_text":"Сумма произведенного платежа, недостаточная для исполнения денежного обязательства полностью, при отсутствии иного соглашения погашает прежде всего издержки кредитора по получению исполнения, затем - проценты, а в оставшейся части - основную сумму долга.","article_title":"Статья 319. Очередность погашения требований по денежному обязательству","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"726ddb9da2dd52e13329c990e86f16dffe9025ca88ae7b6ae2ea0e4f309c9c0e"},{"code_id":"GK_RF","article_number":"319.1","version_date":"1994-11-30","article_text":"1. В случае, если исполненного должником недостаточно для погашения всех однородных обязательств должника перед кредитором, исполненное засчитывается в счет обязательства, указанного должником при исполнении или без промедления после исполнения.\n\n2. Если иное не предусмотрено законом или соглашением сторон, в случаях, когда должник не указал, в счет какого из однородных обязательств осуществлено исполнение, и среди таких обязательств имеются те, по которым кредитор имеет обеспечение, исполнение засчитывается в пользу обязательств, по которым кредитор не имеет обеспечения.\n\n3. Если иное не предусмотрено законом или соглашением сторон, в случаях, когда должник не указал, в счет какого из однородных обязательств осуществлено исполнение, преимущество имеет то обязательство, срок исполнения которого наступил или наступит раньше, либо, когда обязательство не имеет срока исполнения, то обязательство, которое возникло раньше. Если сроки исполнения обязательств наступили одновременно, исполненное засчитывается пропорционально в погашение всех однородных требований.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 319.1. Погашение требований по однородным обязательствам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c0e158255fddf8028c014ec059fb8e545795ab6c2116b918a18377178449f06"},{"code_id":"GK_RF","article_number":"32","version_date":"1994-11-30","article_text":"1. Опека устанавливается над малолетними, а также над гражданами, признанными судом недееспособными вследствие психического расстройства.\n\n2. Опекуны являются представителями подопечных в силу закона и совершают от их имени и в их интересах все необходимые сделки.","article_title":"Статья 32. Опека","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca1b53c97512b6b3aa586973834c91245b7cfdb70f86da9d8b8e36b1e00d8330"},{"code_id":"GK_RF","article_number":"320","version_date":"1994-11-30","article_text":"1. Если должник по альтернативному обязательству (статья 3081), имеющий право выбора, не сделал выбор в пределах установленного для этого срока, в том числе путем исполнения обязательства, кредитор по своему выбору вправе потребовать от должника совершения соответствующего действия или воздержаться от совершения действия.\n\n2. Если право выбора по альтернативному обязательству (статья 3081) предоставлено кредитору или третьему лицу и такой кредитор или третье лицо не сделали выбор в пределах установленного для этого срока, должник исполняет обязательство по своему выбору.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 320. Исполнение альтернативного обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13e63b4cca8b24ef2fb851c4aa76358a5e68569af4ec305620d7e77c5714f264"},{"code_id":"GK_RF","article_number":"320.1","version_date":"1994-11-30","article_text":"1. Если должник по факультативному обязательству (статья 3082) к установленному сроку не приступил к основному исполнению, кредитор вправе потребовать основного исполнения обязательства.\n\n2. К обязательству, предусматривающему совершение должником одного из двух или нескольких действий, применяются правила об исполнении альтернативного обязательства (статья 320), если оно не может быть признано факультативным обязательством.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 320.1. Исполнение факультативного обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b031056310120e7a85ac1c09779d21070fe2f36c1516f5eaa9e5aec4538c58b"},{"code_id":"GK_RF","article_number":"321","version_date":"1994-11-30","article_text":"Если в обязательстве участвуют несколько кредиторов или несколько должников, то каждый из кредиторов имеет право требовать исполнения, а каждый из должников обязан исполнить обязательство в равной доле с другими постольку, поскольку из закона, иных правовых актов или условий обязательства не вытекает иное.","article_title":"Статья 321. Исполнение обязательства, в котором участвуют несколько кредиторов или несколько должников","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b9dbc0afe76777d75a9db6edd65526971861484a7211dc4e8509060676bf1b7"},{"code_id":"GK_RF","article_number":"322","version_date":"1994-11-30","article_text":"1. Солидарная обязанность (ответственность) или солидарное требование возникает, если солидарность обязанности или требования предусмотрена договором или установлена законом, в частности при неделимости предмета обязательства.\n\n2. Обязанности нескольких должников по обязательству, связанному с предпринимательской деятельностью, равно как и требования нескольких кредиторов в таком обязательстве, являются солидарными, если законом, иными правовыми актами или условиями обязательства не предусмотрено иное.","article_title":"Статья 322. Солидарные обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"336acb6a6da69d32db6d3b59da9b12f7b4db076c2e0948658fd1d1db04423986"},{"code_id":"GK_RF","article_number":"323","version_date":"1994-11-30","article_text":"1. При солидарной обязанности должников кредитор вправе требовать исполнения как от всех должников совместно, так и от любого из них в отдельности, притом как полностью, так и в части долга.\n\n2. Кредитор, не получивший полного удовлетворения от одного из солидарных должников, имеет право требовать недополученное от остальных солидарных должников.\n\nСолидарные должники остаются обязанными до тех пор, пока обязательство не исполнено полностью.","article_title":"Статья 323. Права кредитора при солидарной обязанности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"db39c35c77126d9c5bfa5a87ff19f85219c3bac48392cfcadd2beff81ad0a8b2"},{"code_id":"GK_RF","article_number":"324","version_date":"1994-11-30","article_text":"В случае солидарной обязанности должник не вправе выдвигать против требования кредитора возражения, основанные на таких отношениях других должников с кредитором, в которых данный должник не участвует.","article_title":"Статья 324. Возражения против требований кредитора при солидарной обязанности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"834e974e833e91bc3eb7673bcc307a841e7d5b9811d7fb8986535d6ffaeffa22"},{"code_id":"GK_RF","article_number":"325","version_date":"1994-11-30","article_text":"1. Исполнение солидарной обязанности полностью одним из должников освобождает остальных должников от исполнения кредитору.\n\n2. Если иное не вытекает из отношений между солидарными должниками:\n\n1) должник, исполнивший солидарную обязанность, имеет право регрессного требования к остальным должникам в равных долях за вычетом доли, падающей на него самого;\n\n2) неуплаченное одним из солидарных должников должнику, исполнившему солидарную обязанность, падает в равной доле на этого должника и на остальных должников.\n\n3. Правила настоящей статьи применяются соответственно при прекращении солидарного обязательства зачетом встречного требования одного из должников.","article_title":"Статья 325. Исполнение солидарной обязанности одним из должников","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b1a1769a52382dfba531763ea373e74f77a19999903e7e1d34eecbe1fa77551"},{"code_id":"GK_RF","article_number":"326","version_date":"1994-11-30","article_text":"1. При солидарности требования любой из солидарных кредиторов вправе предъявить к должнику требование в полном объеме.\n\nДо предъявления требования одним из солидарных кредиторов должник вправе исполнять обязательство любому из них по своему усмотрению.\n\n2. Должник не вправе выдвигать против требования одного из солидарных кредиторов возражения, основанные на таких отношениях должника с другим солидарным кредитором, в которых данный кредитор не участвует.\n\n3. Исполнение обязательства полностью одному из солидарных кредиторов освобождает должника от исполнения остальным кредиторам.\n\n4. Солидарный кредитор, получивший исполнение от должника, обязан возместить причитающееся другим кредиторам в равных долях, если иное не вытекает из отношений между ними.","article_title":"Статья 326. Солидарные требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"388f9a7b8d228a45da85e3aa8be71dd1af39e06c9ec36bab331c6b1ad7a8a216"},{"code_id":"GK_RF","article_number":"327","version_date":"1994-11-30","article_text":"1. Должник вправе внести причитающиеся с него деньги или ценные бумаги в депозит нотариуса, а в случаях, установленных законом, в депозит суда - если обязательство не может быть исполнено должником вследствие:\n\n1) отсутствия кредитора или лица, уполномоченного им принять исполнение, в месте, где обязательство должно быть исполнено;\n\n2) недееспособности кредитора и отсутствия у него представителя;\n\n3) очевидного отсутствия определенности по поводу того, кто является кредитором по обязательству, в частности в связи со спором по этому поводу между кредитором и другими лицами;\n\n4) уклонения кредитора от принятия исполнения или иной просрочки с его стороны.\n\n2. Внесение денежной суммы или ценных бумаг в депозит нотариуса или суда считается исполнением обязательства.\n\nНотариус или суд, в депозит которого внесены деньги или ценные бумаги, извещает об этом кредитора.","article_title":"Статья 327. Исполнение обязательства внесением долга в депозит","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ffbc617dee40d908fe8117032e572b56d7c26494b6c1b5cd0443625f8ecec7cf"},{"code_id":"GK_RF","article_number":"327.1","version_date":"1994-11-30","article_text":"Исполнение обязанностей, а равно и осуществление, изменение и прекращение определенных прав по договорному обязательству, может быть обусловлено совершением или несовершением одной из сторон обязательства определенных действий либо наступлением иных обстоятельств, предусмотренных договором, в том числе полностью зависящих от воли одной из сторон.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 327.1. Обусловленное исполнение обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d903ca0bd9b1f381256737b11da76018515900a57bd6a7e45f3974394acb39b"},{"code_id":"GK_RF","article_number":"328","version_date":"1994-11-30","article_text":"1. Встречным признается исполнение обязательства одной из сторон, которое обусловлено исполнением другой стороной своих обязательств.\n\n2. В случае непредоставления обязанной стороной предусмотренного договором исполнения обязательства либо при наличии обстоятельств, очевидно свидетельствующих о том, что такое исполнение не будет произведено в установленный срок, сторона, на которой лежит встречное исполнение, вправе приостановить исполнение своего обязательства или отказаться от исполнения этого обязательства и потребовать возмещения убытков.\n\nЕсли предусмотренное договором исполнение обязательства произведено не в полном объеме, сторона, на которой лежит встречное исполнение, вправе приостановить исполнение своего обязательства или отказаться от исполнения в части, соответствующей непредоставленному исполнению.\n\n3. Ни одна из сторон обязательства, по условиям которого предусмотрено встречное исполнение, не вправе требовать по суду исполнения, не предоставив причитающегося с нее по обязательству другой стороне.\n\n4. Правила, предусмотренные пунктами 2 и 3 настоящей статьи, применяются, если законом или договором не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 328. Встречное исполнение обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"73ae8f7a75f50567a8c2ec86f678e602edb92e71fefc329e0d511aaad21ac0b8"},{"code_id":"GK_RF","article_number":"329","version_date":"1994-11-30","article_text":"1. Исполнение обязательств может обеспечиваться неустойкой, залогом, удержанием вещи должника, поручительством, независимой гарантией, задатком, обеспечительным платежом и другими способами, предусмотренными законом или договором.\n\n2. Недействительность соглашения об обеспечении исполнения обязательства не влечет недействительности соглашения, из которого возникло основное обязательство.\n\n3. При недействительности соглашения, из которого возникло основное обязательство, обеспеченными считаются связанные с последствиями такой недействительности обязанности по возврату имущества, полученного по основному обязательству.\n\n4. Прекращение основного обязательства влечет прекращение обеспечивающего его обязательства, если иное не предусмотрено законом или договором.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 329. Способы обеспечения исполнения обязательств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c2ba6a86838e5d94005ab87aef1c30b1dd76ee13b97126c05a23634b93db244e"},{"code_id":"GK_RF","article_number":"33","version_date":"1994-11-30","article_text":"Попечители несовершеннолетних граждан и граждан, дееспособность которых ограничена вследствие психического расстройства, оказывают подопечным содействие в осуществлении ими своих прав и исполнении обязанностей, а также охраняют их от злоупотреблений со стороны третьих лиц.\n\n(Пункт в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 33. Попечительство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"747e4ab2796d021a1dbdf818478f69a56e35ea1b4ed5efe1632caa188cd7ba12"},{"code_id":"GK_RF","article_number":"330","version_date":"1994-11-30","article_text":"1. Неустойкой (штрафом, пеней) признается определенная законом или договором денежная сумма, которую должник обязан уплатить кредитору в случае неисполнения или ненадлежащего исполнения обязательства, в частности в случае просрочки исполнения. По требованию об уплате неустойки кредитор не обязан доказывать причинение ему убытков.\n\n2. Кредитор не вправе требовать уплаты неустойки, если должник не несет ответственности за неисполнение или ненадлежащее исполнение обязательства.","article_title":"Статья 330. Понятие неустойки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e7f6335e2583a181aec84a5b421f60eedb4cd5494dbcbc0ecdb8e371a3107ca5"},{"code_id":"GK_RF","article_number":"331","version_date":"1994-11-30","article_text":"Соглашение о неустойке должно быть совершено в письменной форме независимо от формы основного обязательства.\n\nНесоблюдение письменной формы влечет недействительность соглашения о неустойке.","article_title":"Статья 331. Форма соглашения о неустойке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1afba1ba8f418e723f9843658a2c8024f4d7353ab8fa93bddd10e8be45761297"},{"code_id":"GK_RF","article_number":"332","version_date":"1994-11-30","article_text":"1. Кредитор вправе требовать уплаты неустойки, определенной законом (законной неустойки), независимо от того, предусмотрена ли обязанность ее уплаты соглашением сторон.\n\n2. Размер законной неустойки может быть увеличен соглашением сторон, если закон этого не запрещает.","article_title":"Статья 332. Законная неустойка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6dc607d3e8c14554e46bd543670eeaea44f27113390697c368c3dc4cc1751bb"},{"code_id":"GK_RF","article_number":"333","version_date":"1994-11-30","article_text":"1. Если подлежащая уплате неустойка явно несоразмерна последствиям нарушения обязательства, суд вправе уменьшить неустойку. Если обязательство нарушено лицом, осуществляющим предпринимательскую деятельность, суд вправе уменьшить неустойку при условии заявления должника о таком уменьшении.\n\n2. Уменьшение неустойки, определенной договором и подлежащей уплате лицом, осуществляющим предпринимательскую деятельность, допускается в исключительных случаях, если будет доказано, что взыскание неустойки в предусмотренном договором размере может привести к получению кредитором необоснованной выгоды.\n\n3. Правила настоящей статьи не затрагивают право должника на уменьшение размера его ответственности на основании статьи 404 настоящего Кодекса и право кредитора на возмещение убытков в случаях, предусмотренных статьей 394 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\n(Параграф в редакции Федерального закона от 21.12.2013 № 367-ФЗ)\n\n1. Общие положения о залоге","article_title":"Статья 333. Уменьшение неустойки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f11cf91b933d751fdc3eb2dca3ff7c116acf121ccee21a19b17f2e0372f55f42"},{"code_id":"GK_RF","article_number":"334","version_date":"1994-11-30","article_text":"1. В силу залога кредитор по обеспеченному залогом обязательству (залогодержатель) имеет право в случае неисполнения или ненадлежащего исполнения должником этого обязательства получить удовлетворение из стоимости заложенного имущества (предмета залога) преимущественно перед другими кредиторами лица, которому принадлежит заложенное имущество (залогодателя).\n\nВ случаях и в порядке, которые предусмотрены законом, требование залогодержателя может быть удовлетворено путем передачи предмета залога залогодержателю (оставления у залогодержателя).\n\n2. Залогодержатель преимущественно перед другими кредиторами залогодателя вправе получить удовлетворение обеспеченного залогом требования также за счет:\n\nстрахового возмещения за утрату или повреждение заложенного имущества независимо от того, в чью пользу оно застраховано, если только утрата или повреждение произошли не по причинам, за которые залогодержатель отвечает;\n\nпричитающегося залогодателю возмещения, предоставляемого взамен заложенного имущества, в частности если право собственности залогодателя на имущество, являющееся предметом залога, прекращается по основаниям и в порядке, которые установлены законом, вследствие изъятия (выкупа) для государственных или муниципальных нужд, реквизиции или национализации, а также в иных случаях, предусмотренных законом;\n\nпричитающихся залогодателю или залогодержателю доходов от использования заложенного имущества третьими лицами;\n\nимущества, причитающегося залогодателю при исполнении третьим лицом обязательства, право требовать исполнения которого является предметом залога.\n\nВ случаях, указанных в абзацах втором - пятом настоящего пункта, залогодержатель вправе требовать причитающиеся ему денежную сумму или иное имущество непосредственно от обязанного лица, если иное не предусмотрено законом или договором.\n\n3. Если иное не предусмотрено законом или договором, при недостаточности суммы, вырученной в результате обращения взыскания на заложенное имущество, для погашения требования залогодержатель вправе удовлетворить свое требование в непогашенной части за счет иного имущества должника, не пользуясь преимуществом, основанным на залоге.\n\nЕсли сумма, вырученная в результате обращения взыскания на заложенное имущество, превышает размер обеспеченного залогом требования залогодержателя, разница возвращается залогодателю. Соглашение об отказе залогодателя от права на получение указанной разницы ничтожно.\n\n4. К отдельным видам залога (статьи 357 - 35817) применяются общие положения о залоге, если иное не предусмотрено правилами настоящего Кодекса об эт\n\nих видах залога.\n\nК залогу недвижимого имущества (ипотеке) применяются правила настоящего Кодекса о вещных правах, а в части, не урегулированной указанными правилами и законом об ипотеке, общие положения о залоге.\n\n5. Если иное не вытекает из существа отношений залога, кредитор или иное управомоченное лицо, в чьих интересах был наложен запрет на распоряжение имуществом (статья 1741), обладает правами и обязанностями залогодержателя в отношении этого имущества с момента вступления в силу решения суда, которым требования таких кредитора или иного управомоченного лица были удовлетворены. Очередность удовлетворения указанных требований определяется в соответствии с положениями статьи 3421 настоящего Кодекса по дате, на которую соответствующий запрет считается возникшим.","article_title":"Статья 334. Понятие залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d7a5979b60be3e44c9ba5c1210e7169d3954230f36dadfafff302b221ead926f"},{"code_id":"GK_RF","article_number":"334.1","version_date":"1994-11-30","article_text":"1. Залог между залогодателем и залогодержателем возникает на основании договора. В случаях, установленных законом, залог возникает при наступлении указанных в законе обстоятельств (залог на основании закона).\n\n2. Правила настоящего Кодекса о залоге на основании договора соответственно применяются к залогу, возникшему на основании закона, если законом не установлено иное.\n\n3. В случае возникновения залога на основании закона залогодатель и залогодержатель вправе заключить соглашение, регулирующее их отношения. К такому соглашению применяются правила настоящего Кодекса о форме договора залога.","article_title":"Статья 334.1. Основания возникновения залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0170f0addca6440ed5149eed4f92d656cd0a5fa510bc4bed7d8f6022ac32a220"},{"code_id":"GK_RF","article_number":"335","version_date":"1994-11-30","article_text":"1. Залогодателем может быть как сам должник, так и третье лицо.\n\nВ случае, когда залогодателем является третье лицо, к отношениям между залогодателем, должником и залогодержателем применяются правила статей 364 - 367 настоящего Кодекса, если законом или соглашением между соответствующими лицами не предусмотрено иное.\n\n2. Право передачи вещи в залог принадлежит собственнику вещи. Лицо, имеющее иное вещное право, может передавать вещь в залог в случаях, предусмотренных настоящим Кодексом.\n\nЕсли вещь передана в залог залогодержателю лицом, которое не являлось ее собственником или иным образом не было надлежаще управомочено распоряжаться имуществом, о чем залогодержатель не знал и не должен был знать (добросовестный залогодержатель), собственник заложенного имущества имеет права и несет обязанности залогодателя, предусмотренные настоящим Кодексом, другими законами и договором залога.\n\nПравила, предусмотренные абзацем вторым настоящего пункта, не применяются, если вещь, переданная в залог, была утеряна до этого собственником или лицом, которому вещь была передана собственником во владение, либо была похищена у того или другого, либо выбыла из их владения иным путем помимо их воли.\n\n3. Если предметом залога является имущество, на отчуждение которого требуется согласие или разрешение другого лица либо уполномоченного органа, такое же согласие или такое же разрешение необходимо для передачи этого имущества в залог, за исключением случаев, когда залог возникает в силу закона.\n\n4. В случае, если имущество залогодателя, являющееся предметом залога, перешло в порядке правопреемства к нескольким лицам, каждый из правопреемников (приобретателей имущества) несет вытекающие из залога последствия неисполнения обеспеченного залогом обязательства соразмерно перешедшей к нему части указанного имущества. Если предмет залога неделим или по иным основаниям остается в общей собственности правопреемников, они становятся солидарными созалогодателями.","article_title":"Статья 335. Залогодатель","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b3d59ae76edfb1e58a6ed1cb7b931f1c791dda39184126cfe58f532468e0d260"},{"code_id":"GK_RF","article_number":"335.1","version_date":"1994-11-30","article_text":"1. В случаях, предусмотренных законом или договором, предмет залога может находиться в залоге у нескольких лиц, имеющих на него равные по старшинству права залогодержателей (созалогодержатели), в обеспечение исполнения разных обязательств, по которым созалогодержатели являются самостоятельными кредиторами.\n\nЕсли иное не установлено законом или соглашением между созалогодержателями, каждый из них самостоятельно осуществляет права и обязанности залогодержателя. При обращении взыскания на предмет залога, находящийся в залоге у созалогодержателей, применяются правила пунктов 2 и 6 статьи 3421 настоящего Кодекса.\n\nДенежные суммы, вырученные от реализации предмета залога, распределяются между созалогодержателями пропорционально размерам их требований, обеспеченных залогом, если иное не предусмотрено соглашением между ними или не вытекает из существа отношений между созалогодержателями.\n\n2. Если иное не предусмотрено законом или договором, солидарные или долевые кредиторы по обязательству, исполнение которого обеспечено залогом, являются солидарными созалогодержателями по такому залогу. При обращении взыскания на предмет залога, находящийся в залоге у солидарных созалогодержателей, применяются правила пункта 6 статьи 3421 настоящего Кодекса.\n\nДенежные суммы, вырученные от реализации предмета залога, распределяются между созалогодержателями, являющимися солидарными кредиторами по основному обязательству, в порядке, установленном пунктом 4 статьи 326 настоящего Кодекса. Денежные суммы, вырученные от реализации предмета залога, распределяются между созалогодержателями, являющимися долевыми кредиторами по основному обязательству, пропорционально размерам их требований, обеспеченных залогом, если иное не предусмотрено договором между ними.","article_title":"Статья 335.1. Созалогодержатели","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"594709b6b91ea41d60321926ca826566a2864becfa67d6d9ad30ff945346ffbe"},{"code_id":"GK_RF","article_number":"336","version_date":"1994-11-30","article_text":"1. Предметом залога может быть всякое имущество, в том числе вещи и имущественные права, за исключением имущества, на которое не допускается обращение взыскания, требований, неразрывно связанных с личностью кредитора, в частности требований об алиментах, о возмещении вреда, причиненного жизни или здоровью, и иных прав, уступка которых другому лицу запрещена законом.\n\nЗалог отдельных видов имущества может быть ограничен или запрещен законом.\n\n2. Договором залога или в отношении залога, возникающего на основании закона, законом может быть предусмотрен залог имущества, которое залогодатель приобретет в будущем.\n\n3. На полученные в результате использования заложенного имущества плоды, продукцию и доходы залог распространяется в случаях, предусмотренных законом или договором.\n\n4. При заключении договора залога залогодатель обязан предупредить в письменной форме залогодержателя о всех известных ему к моменту заключения договора правах третьих лиц на предмет залога (вещных правах, правах, возникающих из договоров аренды, ссуды и т.п.). В случае неисполнения залогодателем этой обязанности залогодержатель вправе потребовать досрочного исполнения обеспеченного залогом обязательства или изменения условий договора залога, если иное не предусмотрено законом или договором.","article_title":"Статья 336. Предмет залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6280119419b1eefb70d1e840955a292aa2a20c02c6c982353eb3e8894d115067"},{"code_id":"GK_RF","article_number":"337","version_date":"1994-11-30","article_text":"Если иное не предусмотрено законом или договором, залог обеспечивает требование в том объеме, какой оно имеет к моменту удовлетворения, в частности проценты, неустойку, возмещение убытков, причиненных просрочкой исполнения, а также возмещение необходимых расходов залогодержателя на содержание предмета залога и связанных с обращением взыскания на предмет залога и его реализацией расходов.","article_title":"Статья 337. Обеспечиваемое залогом требование","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"21dc1bdec1ecb98af37fb9cd09fa2a01024e9bf301c4a784b2ead54af45f122b"},{"code_id":"GK_RF","article_number":"338","version_date":"1994-11-30","article_text":"1. Заложенное имущество остается у залогодателя, если иное не предусмотрено настоящим Кодексом, другим законом или договором.\n\n2. Предмет залога может быть оставлен у залогодателя под замком и печатью залогодержателя.\n\nПредмет залога может быть оставлен у залогодателя с наложением знаков, свидетельствующих о залоге (твердый залог).\n\n3. Предмет залога, переданный залогодателем на время во владение или в пользование третьему лицу, считается оставленным у залогодателя.","article_title":"Статья 338. Владение предметом залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a62676de9b076efe4699692fbf937619714f7af313a70d4270c215a1bcedb1de"},{"code_id":"GK_RF","article_number":"339","version_date":"1994-11-30","article_text":"1. В договоре залога должны быть указаны предмет залога, существо, размер и срок исполнения обязательства, обеспечиваемого залогом. Условия, относящиеся к основному обязательству, считаются согласованными, если в договоре залога имеется отсылка к договору, из которого возникло или возникнет в будущем обеспечиваемое обязательство.\n\nСтороны могут предусмотреть в договоре залога условие о порядке реализации заложенного имущества, взыскание на которое обращено по решению суда, или условие о возможности обращения взыскания на заложенное имущество во внесудебном порядке.\n\n2. В договоре залога, залогодателем по которому является лицо, осуществляющее предпринимательскую деятельность, обязательство, обеспечиваемое залогом, включая будущее обязательство, может быть описано способом, позволяющим определить обязательство в качестве обязательства, обеспеченного залогом, на момент обращения взыскания, в том числе путем указания на обеспечение всех существующих и (или) будущих обязательств должника перед кредитором в пределах определенной суммы.\n\nВ договоре залога, залогодателем по которому является лицо, осуществляющее предпринимательскую деятельность, предмет залога может быть описан любым способом, позволяющим идентифицировать имущество в качестве предмета залога на момент обращения взыскания, в том числе путем указания на залог всего имущества залогодателя или определенной части его имущества либо на залог имущества определенных рода или вида.\n\n3. Договор залога должен быть заключен в простой письменной форме, если законом или соглашением сторон не установлена нотариальная форма.\n\nДоговор залога в обеспечение исполнения обязательств по договору, который должен быть нотариально удостоверен, подлежит нотариальному удостоверению.\n\nНесоблюдение правил, содержащихся в настоящем пункте, влечет недействительность договора залога.","article_title":"Статья 339. Условия и форма договора залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5d41b1f02b29fd778f82aba75f1a9382721337f709de664d510633c78f9c82da"},{"code_id":"GK_RF","article_number":"339.1","version_date":"1994-11-30","article_text":"1. Залог подлежит государственной регистрации и возникает с момента такой регистрации в следующих случаях:\n\n1) если в соответствии с законом права, закрепляющие принадлежность имущества определенному лицу, подлежат государственной регистрации (статья 81);\n\n2) если предметом залога являются права участника (учредителя) общества с ограниченной ответственностью (статья 35815).\n\n2. Записи о залоге ценных бумаг совершаются в соответствии с правилами настоящего Кодекса и других законов о ценных бумагах.\n\n3. Сведения о залоге прав по договору банковского счета учитываются в соответствии с правилами статьи 35811 настоящего Кодекса.\n\n4. Залог иного имущества, не относящегося к недвижимым вещам, помимо указанного в пунктах 1 - 3 настоящей статьи имущества, может быть учтен путем регистрации уведомлений о залоге, поступивших от залогодателя, залогодержателя или в случаях, установленных законодательством о нотариате, от другого лица, в реестре уведомлений о залоге такого имущества (реестр уведомлений о залоге движимого имущества). Реестр уведомлений о залоге движимого имущества ведется в порядке, установленном законодательством о нотариате.\n\nВ случае изменения или прекращения залога, в отношении которого зарегистрировано уведомление о залоге, залогодержатель обязан направить в порядке, установленном законодательством о нотариате, уведомление об изменении залога или об исключении сведений о залоге в течение трех рабочих дней с момента, когда он узнал или должен был узнать об изменении или о прекращении залога. В случаях, предусмотренных законодательством о нотариате, уведомление об изменении залога или об исключении сведений о залоге направляет иное указанное в законе лицо.\n\nЗалогодержатель в отношениях с третьими лицами вправе ссылаться на принадлежащее ему право залога только с момента совершения записи об учете залога, за исключением случаев, если третье лицо знало или должно было знать о существовании залога ранее этого. Отсутствие записи об учете не затрагивает отношения залогодателя с залогодержателем.","article_title":"Статья 339.1. Государственная регистрация и учет залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5bb7b059275d1c092cc48f26ecb878421c27994d87dce63e7e75b11a7b31241"},{"code_id":"GK_RF","article_number":"34","version_date":"1994-11-30","article_text":"Абзац. (Дополнение абзацем - Федеральный закон от 02.07.2013 № 167-ФЗ) (Утратил силу - Федеральный закон от 08.08.2024 № 237-ФЗ)\n\nПолномочия органа опеки и попечительства в отношении подопечного возлагаются на орган, который установил опеку или попечительство. При перемене места жительства подопечного полномочия органа опеки и попечительства возлагаются на орган опеки и попечительства по новому месту жительства подопечного в порядке, определенном Федеральным законом \"Об опеке и попечительстве\". (Дополнение абзацем - Федеральный закон от 24.04.2008 № 49-ФЗ)","article_title":"Статья 34. Органы опеки и попечительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a9a03a0fbfac040706bf795b731b3306e3186e188bb8b6bd6a127a3dd8f7be2"},{"code_id":"GK_RF","article_number":"340","version_date":"1994-11-30","article_text":"1. Стоимость предмета залога определяется по соглашению сторон, если иное не предусмотрено законом.\n\n2. Если иное не предусмотрено законом или договором, изменение рыночной стоимости предмета залога после заключения договора залога или возникновения залога в силу закона не является основанием для изменения или прекращения залога.\n\nУсловия договора, которые предусматривают в связи с последующим уменьшением рыночной стоимости предмета залога, обеспечивающего обязательство гражданина по возврату потребительского или ипотечного кредита, распространение залога на иное имущество, досрочный возврат кредита или иные неблагоприятные для залогодателя последствия, ничтожны.\n\n3. Если иное не предусмотрено законом, соглашением сторон или решением суда об обращении взыскания на заложенное имущество, согласованная сторонами стоимость предмета залога признается ценой реализации (начальной продажной ценой) предмета залога при обращении на него взыскания.","article_title":"Статья 340. Стоимость предмета залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb8cf6778202550c0e9e2bbce5f6d349491db9875b4bf7cfef8f43f8f01be042"},{"code_id":"GK_RF","article_number":"341","version_date":"1994-11-30","article_text":"1. Права залогодержателя в отношениях с залогодателем возникают с момента заключения договора залога, если иное не установлено договором, настоящим Кодексом и другими законами.\n\n2. Если предметом залога является имущество, которое будет создано или приобретено залогодателем в будущем, залог возникает у залогодержателя с момента создания или приобретения залогодателем соответствующего имущества, за исключением случая, когда законом или договором предусмотрено, что оно возникает в иной срок.\n\n3. Если основное обязательство, обеспечиваемое залогом, возникнет в будущем после заключения договора залога, залог возникает с момента, определенного договором, но не ранее возникновения этого обязательства. С момента заключения такого договора залога к отношениям сторон применяются положения статей 343 и 346 настоящего Кодекса.\n\n4. Законом в отношении залога недвижимого имущества может быть предусмотрено, что залог считается возникшим, существует и прекращается независимо от возникновения, существования и прекращения обеспеченного обязательства.","article_title":"Статья 341. Возникновение залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d36e8fef71490c0d5e6990ce5521598e092ba1c812fd4d74bd6f368826604bc"},{"code_id":"GK_RF","article_number":"342","version_date":"1994-11-30","article_text":"1. В случаях, если имущество, находящееся в залоге, становится предметом еще одного залога в обеспечение других требований (последующий залог), требования последующего залогодержателя удовлетворяются из стоимости этого имущества после требований предшествующих залогодержателей.\n\nСтаршинство залогов может быть изменено:\n\nсоглашением между залогодержателями;\n\nсоглашением между одним, несколькими или всеми залогодержателями и залогодателем.\n\nВо всяком случае указанные соглашения не затрагивают права третьих лиц, не являющихся сторонами указанных соглашений.\n\n2. Последующий залог допускается, если иное не установлено законом.\n\nЕсли предшествующий договор залога предусматривает условия, на которых может быть заключен последующий договор залога, такой договор залога должен быть заключен с соблюдением указанных условий. При нарушении указанных условий предшествующий залогодержатель вправе требовать от залогодателя возмещения причиненных этим убытков.\n\n3. Залогодатель обязан сообщать каждому последующему залогодержателю сведения о всех существующих залогах имущества, предусмотренные пунктом 1 статьи 339 настоящего Кодекса, и отвечает за убытки, причиненные последующим залогодержателям вследствие невыполнения этой обязанности, если не докажет, что залогодержатель знал или должен был знать о предшествующих залогах.\n\n4. Залогодатель, заключивший последующий договор залога, незамедлительно должен уведомить об этом залогодержателей по предшествующим залогам и по их требованию сообщить сведения о последующем залоге, предусмотренные пунктом 1 статьи 339 настоящего Кодекса.\n\n5. Если последующий договор залога заключен с нарушением условий, предусмотренных для него предшествующим договором залога, о чем залогодержатель по последующему договору знал или должен был знать, его требования к залогодателю удовлетворяются с учетом условий предшествующего договора залога.\n\n6. Изменение предшествующего договора залога после заключения последующего договора залога, если последующий договор залога заключен с соблюдением условий, предусмотренных для него предшествующим договором залога, или такие условия не были предусмотрены предшествующим договором залога, не затрагивает права последующего залогодержателя при условии, что такое изменение влечет ухудшение обеспечения его требования и произведено без согласия последующего залогодержателя.","article_title":"Статья 342. Соотношение предшествующего и последующего залогов (старшинство залогов)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0b63caa642c06e27ae23a2a60bf6051294e6633e3b48a8f7bacaab1baa299d27"},{"code_id":"GK_RF","article_number":"342.1","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено настоящим Кодексом или другим законом, очередность удовлетворения требований залогодержателей устанавливается в зависимости от момента возникновения каждого залога.\n\nНезависимо от момента возникновения залога, если будет доказано, что залогодержатель на момент заключения договора или на момент возникновения обстоятельств, с которыми закон связывает возникновение залога, знал или должен был знать о наличии предшествующего залогодержателя, требования такого предшествующего залогодержателя удовлетворяются преимущественно.\n\n2. В случае обращения взыскания на заложенное имущество предшествующим залогодержателем последующий залогодержатель вправе потребовать от должника досрочного исполнения обязательства, обеспеченного последующим залогом, и в случае его неисполнения обратить взыскание на заложенное имущество одновременно с предшествующим залогодержателем. Договором между залогодателем и последующим залогодержателем может быть ограничено право такого залогодержателя потребовать от должника досрочного исполнения обязательства, обеспеченного последующим залогом.\n\n3. Требование, обеспеченное последующим залогом, не подлежит досрочному удовлетворению, если оставшегося после обращения взыскания предшествующим залогодержателем заложенного имущества будет достаточно для удовлетворения требования последующего залогодержателя.\n\n4. Если последующий залогодержатель не воспользовался правом потребовать досрочного исполнения обязательства или данное право было ограничено соглашением в соответствии с пунктом 2 настоящей статьи, последующий залог прекращается, за исключением случаев, предусмотренных пунктом 3 настоящей статьи.\n\n5. Если в отношении заложенного имущества, не относящегося к недвижимым вещам, заключены два и более договора о залоге или совершены иные сделки, повлекшие возникновение залога, и невозможно установить, какая из указанных сделок совершена ранее, требования залогодержателей по таким залогам удовлетворяются пропорционально размерам обеспеченных залогом обязательств.\n\n6. В случае обращения взыскания на заложенное имущество по требованиям, обеспеченным последующим залогом, предшествующий залогодержатель вправе потребовать одновременно досрочного исполнения обеспеченного залогом обязательства и обращения взыскания на это имущество. Если залогодержатель по предшествующему договору залога не воспользовался данным правом, имущество, на которое обращено взыскание по требованиям, обеспеченным последующим залогом, переходит к его приобретателю с обременением предшествующим залогом.\n\n7. До обращения взыскания на имущество, залогом которого обеспечены требования по предшествующему и последующему залогам, залогодержатель, имеющий намерение предъявить свои требования к взысканию, обязан уведомить об этом в письменной форме всех других известных ему залогодержателей этого же имущества.\n\nЗалогодатель, к которому предъявлено требование об обращении взыскания на заложенное имущество одним из залогодержателей, обязан уведомить об этом в письменной форме всех других залогодержателей этого же имущества.\n\n8. После распределения сумм, вырученных от реализации заложенного имущества, между всеми залогодержателями реализованного заложенного имущества, заявившими свои требования к взысканию, в порядке очередности распределяются суммы неустойки, убытков и иных штрафных санкций, подлежащих уплате залогод\n\nержателю в соответствии с условиями обеспеченного обязательства. Иная очередность распределения сумм неустойки, убытков и иных штрафных санкций может быть предусмотрена в соответствии с законами о ценных бумагах.\n\n9. Правила, установленные настоящей статьей, не применяются, если залогодержателем по предшествующему и последующему залогам является одно и то же лицо. В этом случае требования, обеспеченные каждым из залогов, удовлетворяются в порядке очередности, соответствующей срокам исполнения обеспеченных залогом обязательств, если законом или соглашением сторон не предусмотрено иное.\n\n10. В случаях, если заложенное имущество, в отношении которого ведется учет залогов в соответствии с пунктом 4 статьи 3391 настоящего Кодекса, является предметом нескольких залогов, требования залогодержателя, обеспеченные залогом, запись об учете которого совершена ранее, удовлетворяются преимущественно перед требованиями залогодержателя, обеспеченными залогом того же имущества, запись об учете которого не совершена в установленном законом порядке или совершена позднее, независимо от того, какой залог возник ранее. Иной порядок удовлетворения требований залогодержателей может быть предусмотрен в соответствии с законами о ценных бумагах.","article_title":"Статья 342.1. Очередность удовлетворения требований залогодержателей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"288738714f316073fe74ebf62dd21bfd60f0df88701dca6cb1bf54cb03faf922"},{"code_id":"GK_RF","article_number":"343","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором, залогодатель или залогодержатель в зависимости от того, у кого из них находится заложенное имущество (статья 338), обязан:\n\n1) страховать от рисков утраты и повреждения за счет залогодателя заложенное имущество на сумму не ниже размера обеспеченного залогом требования;\n\n2) пользоваться и распоряжаться заложенным имуществом в соответствии с правилами статьи 346 настоящего Кодекса;\n\n3) не совершать действия, которые могут повлечь утрату заложенного имущества или уменьшение его стоимости, и принимать меры, необходимые для обеспечения сохранности заложенного имущества;\n\n4) принимать меры, необходимые для защиты заложенного имущества от посягательств и требований со стороны третьих лиц;\n\n5) немедленно уведомлять другую сторону о возникновении угрозы утраты или повреждения заложенного имущества, о притязаниях третьих лиц на это имущество, о нарушениях третьими лицами прав на это имущество.\n\n2. Залогодержатель и залогодатель вправе проверять по документам и фактически наличие, количество, состояние и условия хранения заложенного имущества, находящегося у другой стороны, не создавая при этом неоправданных помех для правомерного использования заложенного имущества.\n\n3. При грубом нарушении залогодержателем или залогодателем указанных в пункте 1 настоящей статьи обязанностей, создающем угрозу утраты или повреждения заложенного имущества, залогодатель вправе потребовать досрочного прекращения залога, а залогодержатель - досрочного исполнения обязательства, обеспеченного залогом, и в случае его неисполнения - обращения взыскания на заложенное имущество.","article_title":"Статья 343. Содержание и сохранность заложенного имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f44f38ea6c6ecf2c9182550f0be8b727c388226ad8ad9ce3437a71abe86f320e"},{"code_id":"GK_RF","article_number":"344","version_date":"1994-11-30","article_text":"1. Залогодатель несет риск случайной гибели или случайного повреждения заложенного имущества, если иное не предусмотрено договором залога.\n\n2. Залогодержатель отвечает перед залогодателем за полную или частичную утрату или повреждение переданного ему предмета залога, если не докажет, что может быть освобожден от ответственности в соответствии со статьей 401 настоящего Кодекса.\n\nЗалогодержатель отвечает за утрату предмета залога в размере его рыночной стоимости, а за его повреждение в размере суммы, на которую эта стоимость понизилась, независимо от суммы, в которую был оценен предмет залога по договору залога.\n\nЕсли в результате повреждения предмета залога он изменился настолько, что не может быть использован по прямому назначению, залогодатель вправе отказаться от него и потребовать от залогодержателя возмещение за его утрату.\n\nДоговором может быть предусмотрена обязанность залогодержателя возместить залогодателю и иные убытки, причиненные утратой или повреждением предмета залога.\n\n3. Залогодатель, являющийся должником по обеспеченному залогом обязательству, вправе зачесть требование к залогодержателю о возмещении убытков, причиненных утратой или повреждением предмета залога, в погашение обязательства, обеспеченного залогом, в том числе тогда, когда срок исполнения этого обязательства еще не наступил и досрочное исполнение обязательства не допускается.","article_title":"Статья 344. Последствия утраты или повреждения заложенного имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72108ae57fb0d5447195001c2d9f5cc9a0196366c24138b8457950069d3fb676"},{"code_id":"GK_RF","article_number":"345","version_date":"1994-11-30","article_text":"1. По соглашению залогодателя и залогодержателя предмет залога может быть заменен другим имуществом.\n\n2. Независимо от согласия на это залогодателя или залогодержателя считаются находящимися в залоге:\n\n1) новое имущество, которое принадлежит залогодателю и создано либо возникло в результате переработки или иного изменения заложенного имущества;\n\n2) имущество, предоставленное залогодателю взамен предмета залога в случае его изъятия (выкупа) для государственных или муниципальных нужд, реквизиции или национализации по основаниям и в порядке, которые установлены законом, а также право требовать предоставления имущества взамен предмета залога по указанным основаниям;\n\n3) имущество, за исключением денежных средств, переданное залогодателю-кредитору его должником, в случае залога права (требования);\n\n4) иное имущество в случаях, установленных законом.\n\n3. Если замена предмета залога другим имуществом в случае, предусмотренном подпунктом 1 пункта 2 настоящей статьи, произошла в результате действий залогодателя, совершенных в нарушение договора залога, залогодержатель вправе потребовать досрочного исполнения обязательства, обеспеченного залогом, а при его неисполнении - обращения взыскания на новый предмет залога.\n\n4. Если предмет залога погиб или поврежден по обстоятельствам, за которые залогодержатель не отвечает, залогодатель в разумный срок вправе восстановить предмет залога или заменить его другим равноценным имуществом при условии, что договором не предусмотрено иное.\n\nЗалогодатель, намеревающийся воспользоваться правом на восстановление или замену предмета залога, незамедлительно обязан уведомить об этом в письменной форме залогодержателя. Залогодержатель вправе отказаться в письменной форме в срок, установленный договором залога, или, если такой срок не установлен, в разумный срок после получения уведомления от восстановления или замены предмета залога при условии, что прежний и новый предметы залога неравноценны.\n\n5. В случаях, указанных в пункте 2 настоящей статьи, имущество, которое заменяет предмет залога, в том числе право (требование), считается находящимся в залоге вместо прежнего предмета залога с момента возникновения на него прав залогодателя или с момента возникновения права, за исключением случаев, если в соответствии с законом возникновение, переход и обременение прав требуют государственной регистрации.\n\nУсловия договора залога, а также иных соглашений, заключенных сторонами в отношении прежнего предмета залога, применяются к правам и обязанностям сторон в отношении нового предмета залога в той мере, в какой они не противоречат существу (свойствам) этого предмета залога.\n\nВ случае замены предмета залога старшинство прав залогодержателей, в том числе возникших до предоставления имущества в качестве замены прежнего предмета залога, не изменяется.\n\n6. Вместо замены предмета залога стороны вправе заключить новый договор залога. С момента возникновения у залогодержателя залога на новый предмет залога прежний договор залога прекращается.\n\n7. Договором залога могут быть предусмотрены случаи, в которых залогодатель вправе заменять предмет залога без согласия залогодержателя.","article_title":"Статья 345. Замена и восстановление предмета залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9468c227ce7098ebd02e1c084c1aff887c0bce89deef0782ac11a4a0191daab"},{"code_id":"GK_RF","article_number":"346","version_date":"1994-11-30","article_text":"1. Залогодатель, у которого остается предмет залога, вправе пользоваться, если иное не предусмотрено договором и не вытекает из существа залога, предметом залога в соответствии с его назначением, в том числе извлекать из него плоды и доходы.\n\n2. Залогодатель не вправе отчуждать предмет залога без согласия залогодержателя, если иное не предусмотрено законом или договором и не вытекает из существа залога.\n\nВ случае отчуждения залогодателем заложенного имущества без согласия залогодержателя применяются правила, установленные подпунктом 3 пункта 2 статьи 351, подпунктом 2 пункта 1 статьи 352, статьей 353 настоящего Кодекса. Залогодатель также обязан возместить убытки, причиненные залогодержателю в результате отчуждения заложенного имущества.\n\n3. Если иное не предусмотрено законом или договором залога, залогодатель, у которого осталось заложенное имущество, вправе передавать без согласия залогодержателя заложенное имущество во временное владение или пользование другим лицам. В этом случае залогодатель не освобождается от исполнения обязанностей по договору залога.\n\nЕсли для передачи залогодателем заложенного имущества во временное владение или пользование другим лицам необходимо согласие залогодержателя, при нарушении залогодателем этого условия применяются правила, установленные подпунктом 3 пункта 2 статьи 351 настоящего Кодекса.\n\n4. В случае обращения залогодержателем взыскания на заложенное имущество вещные права, право, возникающее из договора аренды, иные права, возникающие из сделок по предоставлению имущества во владение или в пользование, которые предоставлены залогодателем третьим лицам без согласия залогодержателя, прекращаются с момента вступления в законную силу решения суда об обращении взыскания на заложенное имущество или, если требование залогодержателя удовлетворяется без обращения в суд (во внесудебном порядке), с момента возникновения права собственности на заложенное имущество у его приобретателя при условии, что приобретатель не согласится с сохранением указанных прав.\n\n5. Залогодержатель вправе пользоваться переданным ему предметом залога только в случаях, предусмотренных договором, регулярно представляя залогодателю отчет о пользовании. По договору на залогодержателя может быть возложена обязанность извлекать из предмета залога плоды и доходы в целях погашения основного обязательства или в интересах залогодателя.","article_title":"Статья 346. Пользование и распоряжение предметом залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2d5576fa2bb17baa25f2f0a0fb481d46aa1138577113a3c31da9fb74aba8654"},{"code_id":"GK_RF","article_number":"347","version_date":"1994-11-30","article_text":"1. С момента возникновения залога залогодержатель, у которого находилось или должно было находиться заложенное имущество, вправе истребовать его из чужого незаконного владения, в том числе из владения залогодателя.\n\n2. В случаях, если залогодержателю предоставлено право пользоваться переданным ему предметом залога, он может требовать от других лиц, в том числе от залогодателя, устранения всяких нарушений его права, хотя бы эти нарушения и не были соединены с лишением владения.\n\nЗалогодержатель также вправе требовать освобождения заложенного имущества от ареста (исключения его из описи) в связи с обращением на него взыскания в порядке исполнительного производства.","article_title":"Статья 347. Защита залогодержателем своих прав на предмет залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"07e0709ba822a4856fae9a3052fb5c864aa6f6fa5a16af4623694c76def34828"},{"code_id":"GK_RF","article_number":"348","version_date":"1994-11-30","article_text":"1. Взыскание на заложенное имущество для удовлетворения требований залогодержателя может быть обращено в случае неисполнения или ненадлежащего исполнения должником обеспеченного залогом обязательства.\n\n2. Обращение взыскания на заложенное имущество не допускается, если допущенное должником нарушение обеспеченного залогом обязательства незначительно и размер требований залогодержателя вследствие этого явно несоразмерен стоимости заложенного имущества. Если не доказано иное, предполагается, что нарушение обеспеченного залогом обязательства незначительно и размер требований залогодержателя явно несоразмерен стоимости заложенного имущества при условии, что одновременно соблюдены следующие условия:\n\n1) сумма неисполненного обязательства составляет менее чем пять процентов от размера стоимости заложенного имущества;\n\n2) период просрочки исполнения обязательства, обеспеченного залогом, составляет менее чем три месяца.\n\n3. Если договором залога не предусмотрено иное, обращение взыскания на имущество, заложенное для обеспечения обязательства, исполняемого периодическими платежами, допускается при систематическом нарушении сроков их внесения, то есть при нарушении сроков внесения платежей более чем три раза в течение двенадцати месяцев, предшествующих дате обращения в суд или дате направления уведомления об обращении взыскания на заложенное имущество во внесудебном порядке, даже при условии, что каждая просрочка незначительна.\n\n4. Должник и являющийся третьим лицом залогодатель вправе прекратить в любое время до реализации предмета залога обращение на него взыскания и его реализацию, исполнив обеспеченное залогом обязательство или ту его часть, исполнение которой просрочено. Соглашение, ограничивающее это право, ничтожно.","article_title":"Статья 348. Основания обращения взыскания на заложенное имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ac6747be4e95641a7f2e1a40798831828fe97aa510e1c4f8cdff9f5e7523450"},{"code_id":"GK_RF","article_number":"349","version_date":"1994-11-30","article_text":"1. Обращение взыскания на заложенное имущество осуществляется по решению суда, если соглашением залогодателя и залогодержателя не предусмотрен внесудебный порядок обращения взыскания на заложенное имущество.\n\nЕсли соглашением сторон предусмотрен внесудебный порядок обращения взыскания на заложенное имущество, залогодержатель вправе предъявить в суд требование об обращении взыскания на заложенное имущество. В этом случае дополнительные расходы, связанные с обращением взыскания на заложенное имущество в судебном порядке, возлагаются на залогодержателя, если он не докажет, что обращение взыскания на предмет залога или реализация предмета залога в соответствии с соглашением о внесудебном порядке обращения взыскания не были осуществлены в связи с действиями залогодателя или третьих лиц.\n\nПри обращении взыскания и реализации заложенного имущества залогодержателем и иными лицами должны быть приняты меры, необходимые для получения наибольшей выручки от продажи предмета залога. Лицо, которому причинены убытки неисполнением указанной обязанности, вправе потребовать их возмещения.\n\n2. Удовлетворение требования залогодержателя за счет заложенного имущества без обращения в суд (во внесудебном порядке) допускается на основании соглашения залогодателя с залогодержателем, если иное не предусмотрено законом.\n\n3. Взыскание на предмет залога может быть обращено только по решению суда в случаях, если:\n\nпредметом залога является единственное жилое помещение, принадлежащее на праве собственности гражданину, за исключением случаев заключения после возникновения оснований для обращения взыскания соглашения об обращении взыскания во внесудебном порядке;\n\nпредметом залога является имущество, имеющее значительную историческую, художественную или иную культурную ценность для общества;\n\nзалогодатель - физическое лицо в установленном порядке признано безвестно отсутствующим;\n\nзаложенное имущество является предметом предшествующего и последующего залогов, при которых применяются разный порядок обращения взыскания на предмет залога или разные способы реализации заложенного имущества, если соглашением между предшествующим и последующим залогодержателями не предусмотрено иное;\n\nимущество заложено в обеспечение исполнения разных обязательств нескольким залогодержателям, за исключением случая, когда соглашением всех созалогодержателей с залогодателем предусмотрен внесудебный порядок обращения взыскания.\n\nЗаконом могут быть предусмотрены иные случаи, в которых обращение взыскания на заложенное имущество во внесудебном порядке не допускается.\n\nСоглашения, заключенные с нарушением требований настоящего пункта, ничтожны.\n\n4. Стороны вправе включить условие о внесудебном порядке обращения взыскания в договор залога.\n\n5. Соглашение об обращении взыскания во внесудебном порядке на заложенное имущество должно быть заключено в той же форме, что и договор залога этого имущества.\n\n6. Обращение взыскания на предмет залога по исполнительной надписи нотариуса без обращения в суд допускается в порядке, установленном законодательством о нотариате и законодательством Российской Федерации об исполнительном производстве, в случае неисполнения или ненадлежащего исполнения должником обеспеченного залогом обязательства, если договор залога, содержащий условие об обращении взыскания на заложенное имущество во внесудебном порядке, удостоверен нотариально.\n\n7. Соглашение об обращении взыскания на заложенное имущество во внесудебном порядке должно содержать указание на один способ или несколько способов реализации заложенного имущества, предусмотренных настоящим Кодексом, а также стоимость (начальную продажную цену) заложенного имущества или порядок ее определения.\n\nВ случае, если соглашение об обращении взыскания на заложенное имущество предусматривает несколько способов реализации заложенного имущества, право выбора способа реализации принадлежит залогодержателю при условии, что соглашением не предусмотрено иное.\n\n8. Если обращение взыскания на заложенное имущество осуществляется во внесудебном порядке, залогодержатель или нотариус, который производит обращение взыскания на заложенное имущество в порядке, установленном законодательством о нотариате, обязан направить залогодателю, известным им залогодержателям, а также должнику уведомление о начале обращения взыскания на предмет залога.\n\nРеализация заложенного имущества допускается не ранее чем через десять дней с момента получения залогодателем и должником уведомления залогодержателя или нотариуса, если иной срок не предусмотрен законом, а также если больший срок не предусмотрен соглашением между залогодержателем и залогодателем. В случаях, предусмотренных банковским законодательством, реализация заложенного движимого имущества может быть осуществлена до истечения указанного срока при существенном риске значительного снижения стоимости предмета залога по сравнению с ценой реализации (начальной продажной ценой), указанной в уведомлении.","article_title":"Статья 349. Порядок обращения взыскания на заложенное имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c253b65d7fef88684c7318998641319e975751c1cab3c2c3f0e5198fb35d81a6"},{"code_id":"GK_RF","article_number":"35","version_date":"1994-11-30","article_text":"1. Опекун или попечитель назначается органом опеки и попечительства по месту жительства лица, нуждающегося в опеке или попечительстве, в течение месяца с момента, когда указанным органам стало известно о необходимости установления опеки или попечительства над гражданином. При наличии заслуживающих внимания обстоятельств опекун или попечитель может быть назначен органом опеки и попечительства по месту жительства опекуна (попечителя). Если лицу, нуждающемуся в опеке или попечительстве, в течение месяца не назначен опекун или попечитель, исполнение обязанностей опекуна или попечителя временно возлагается на орган опеки и попечительства.\n\nНазначение опекуна или попечителя может быть оспорено в суде заинтересованными лицами. (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 35. Опекуны и попечители","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c867591a7c1d13ac8c2c851129e6f507fc159e084fb3f2f66ff840998b3fa778"},{"code_id":"GK_RF","article_number":"350","version_date":"1994-11-30","article_text":"1. Реализация заложенного имущества, на которое взыскание обращено на основании решения суда, осуществляется путем продажи с публичных торгов в порядке, установленном настоящим Кодексом и процессуальным законодательством, если законом или соглашением между залогодержателем и залогодателем не установлено, что реализация предмета залога осуществляется в порядке, установленном абзацами вторым и третьим пункта 2 статьи 3501 настоящего Кодекса.\n\n2. При обращении взыскания на заложенное имущество в судебном порядке суд по просьбе залогодателя, являющегося должником по обязательству, при наличии уважительных причин вправе отсрочить продажу заложенного имущества с публичных торгов на срок до одного года.\n\nОтсрочка не освобождает должника от возмещения возросших за время отсрочки убытков кредитора, процентов и неустойки.","article_title":"Статья 350. Реализация заложенного имущества при обращении на него взыскания в судебном порядке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16a49f0c336479325782b1f0dc7d762a64b876bd2187d82b8f6e5bbccfe3e309"},{"code_id":"GK_RF","article_number":"350.1","version_date":"1994-11-30","article_text":"1. В случае, если взыскание на заложенное имущество обращается во внесудебном порядке, его реализация осуществляется посредством продажи с торгов, проводимых в соответствии с правилами, предусмотренными настоящим Кодексом или соглашением между залогодателем и залогодержателем.\n\n2. Если залогодателем является лицо, осуществляющее предпринимательскую деятельность, соглашением между залогодателем и залогодержателем может быть также предусмотрено, что реализация заложенного имущества осуществляется путем:\n\nоставления залогодержателем предмета залога за собой, в том числе посредством поступления предмета залога в собственность залогодержателя, по цене и на иных условиях, которые определены указанным соглашением, но не ниже рыночной стоимости;\n\nпродажи предмета залога залогодержателем другому лицу по цене не ниже рыночной стоимости с удержанием из вырученных денег суммы обеспеченного залогом об\n\nязательства.\n\nВ случае, если стоимость оставляемого за залогодержателем или отчуждаемого третьему лицу имущества превышает размер неисполненного обязательства, обеспеченного залогом, разница подлежит выплате залогодателю.\n\n3. Если при обращении взыскания на заложенное имущество во внесудебном порядке доказано нарушение прав залогодателя или наличие существенного риска такого нарушения, суд может прекратить по требованию залогодателя обращение взыскания на предмет залога во внесудебном порядке и вынести решение об обращении взыскания на предмет залога путем продажи заложенного имущества с публичных торгов (статья 350).\n\n4. В целях реализации заложенного имущества залогодержатель вправе совершать необходимые для этого сделки, а также требовать передачи ему заложенного имущества залогодателем.\n\nЕсли заложенная движимая вещь, оставленная у залогодателя, передана им во владение или в пользование третьему лицу, залогодержатель вправе потребовать от этого лица передачи ему предмета залога.\n\nВ случае отказа передать залогодержателю заложенное имущество для целей его реализации предмет залога может быть изъят и передан залогодержателю по исполнительной надписи нотариуса в соответствии с законодательством о нотариате.\n\n5. Если в соответствии с условиями соглашения залогодателя с залогодержателем реализация заложенного имущества, не относящегося к недвижимым вещам, осуществляется путем продажи залогодержателем этого имущества другому лицу, залогодержатель обязан направить залогодателю заключенный с таким лицом договор купли-продажи.","article_title":"Статья 350.1. Реализация заложенного имущества при обращении на него взыскания во внесудебном порядке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"94c38d23bfcd5ecae61061e615f012c4c1e29719cb48c41b1f900a57eade7eca"},{"code_id":"GK_RF","article_number":"350.2","version_date":"1994-11-30","article_text":"1. При реализации заложенного имущества, не относящегося к недвижимым вещам, с публичных торгов (реализация заложенного имущества с публичных торгов) на основании решения суда судебный пристав - исполнитель обязан направить не позднее чем за десять дней до даты проведения торгов залогодержателю, залогодателю и должнику по основному обязательству уведомление в письменной форме о дате, времени и месте проведения торгов. При реализации заложенного имущества с торгов, проводимых при обращении взыскания на имущество во внесудебном порядке, обязанность по уведомлению залогодателя и должника несет залогодержатель.\n\n2. При реализации заложенного имущества, не относящегося к недвижимым вещам, с публичных торгов на основании решения суда или с торгов, проводимых при обращении взыскания на это имущество во внесудебном порядке, организатор торгов объявляет их не состоявшимися в случаях, если:\n\n1) на торги явилось менее двух покупателей;\n\n2) на торгах не сделана надбавка против начальной продажной цены заложенного имущества;\n\n3) лицо, выигравшее торги, не внесло покупную цену в установленный срок. Торги должны быть объявлены несостоявшимися не позднее чем на следующий день после того, как имело место какое-либо из указанных обстоятельств.\n\n3. Залогодержатель и залогодатель вправе выступать участниками торгов, проводимых на основании решения суда или при обращении взыскания на заложенное имущество во внесудебном порядке. В случае, если залогодержатель выиграл торги, подлежащая уплате им покупная цена зачитывается в счет погашения обязательства, обеспеченного залогом.\n\nПравила, предусмотренные абзацем первым настоящего пункта, применяются в случае оставления залогодержателем предмета залога за собой при обращении взыскания на заложенное имущество во внесудебном порядке.\n\n4. В течение десяти дней после объявления торгов несостоявшимися залогодержатель вправе приобрести по соглашению с залогодателем заложенное имущество, не относящееся к недвижимым вещам, и зачесть в счет покупной цены свои требования, обеспеченные залогом. К такому соглашению применяются правила о договоре купли-продажи.\n\nЕсли соглашение о приобретении имущества залогодержателем, предусмотренное настоящим пунктом, не состоялось, не позднее чем через месяц после первых торгов проводятся повторные торги. Начальная продажная цена заложенного имущества на повторных торгах, если их проведение вызвано причинами, указанными в подпунктах 1 и 2 пункта 2 настоящей статьи, снижается на пятнадцать процентов. При реализации заложенного имущества, не относящегося к недвижимым вещам, с торгов, проводимых при обращении взыскания на это имущество во внесудебном порядке, соглашением сторон может быть предусмотрено, что, если торги были объявлены не состоявшимися по указанным причинам, повторные торги проводятся путем последовательного снижения цены от начальной продажной цены на первых торгах.\n\n5. При объявлении несостоявшимися повторных торгов залогодержатель вправе оставить предмет залога за собой с оценкой его в сумме на десять процентов ниже начальной продажной цены на повторных торгах, если более высокая оценка не установлена соглашением сторон.\n\nЗалогодержатель считается воспользовавшимся указанным правом, когда в течение месяца со дня объявления повторных торгов несостоявшимися направит залогодателю и организатору торгов или, если обращение взыскания осуществлялось в судебном порядке, залогодателю, организатору торгов и судебному приставу - исполнителю заявление в письменной форме об оставлении имущества за собой.\n\nС момента получения в письменной форме залогодателем заявления залогодержателя об оставлении имущества за собой залогодержатель, которому движимая вещь была передана по договору залога, приобретает право собственности на предмет залога, оставленный им за собой, если законом не установлен иной момент возникновения права собственности на движимые вещи соответствующего вида.\n\nЗалогодержатель, оставивший заложенное имущество за собой, вправе требовать передачи ему этого имущества, если оно находится у иного лица.\n\n6. Если залогодержатель не воспользуется правом оставить за собой предмет залога в течение месяца со дня объявления повторных торгов несостоявшимися, договор залога прекращается.\n\n7. Положения настоящего Кодекса о заключении договора на торгах применяются при реализации заложенного имущества с торгов, если иное не установлено настоящей статьей.","article_title":"Статья 350.2. Порядок проведения торгов при реализации заложенного имущества, не относящегося к недвижимым вещам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"35a856dc473bde887f5836125df84b06969552279477ed30b1ed9cbc42f9dc17"},{"code_id":"GK_RF","article_number":"351","version_date":"1994-11-30","article_text":"1. Залогодержатель вправе потребовать досрочного исполнения обеспеченного залогом обязательства в случаях:\n\n1) выбытия предмета залога, оставленного у залогодателя, из его владения не в соответствии с условиями договора залога;\n\n2) гибели или утраты предмета залога по обстоятельствам, за которые залогодержатель не отвечает, если залогодатель не воспользовался правом, предусмотренным пунктом 2 статьи 345 настоящего Кодекса;\n\n3) иных случаях, предусмотренных законом или договором.\n\n2. Поскольку иное не предусмотрено договором, залогодержатель вправе потребовать досрочного исполнения обеспеченного залогом обязательства или, если его требование не будет удовлетворено, обратить взыскание на предмет залога в случаях:\n\n1) нарушения залогодателем правил о последующем залоге (статья 342);\n\n2) невыполнения залогодателем обязанностей, предусмотренных подпунктами 1 и 3 пункта 1 и пунктом 2 статьи 343 настоящего Кодекса;\n\n3) нарушения залогодателем правил об отчуждении заложенного имущества или о предоставлении его во временное владение или пользование третьим лицам (пункты 2 и 4 статьи 346);\n\n4) иных случаях, предусмотренных законом.","article_title":"Статья 351. Досрочное исполнение обязательства, обеспеченного залогом, и обращение взыскания на заложенное имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f74546abd8c256403cc85364cd772c299d07725907bd0c01a94ab85dbb0ef5d0"},{"code_id":"GK_RF","article_number":"352","version_date":"1994-11-30","article_text":"1. Залог прекращается:\n\n1) с прекращением обеспеченного залогом обязательства;\n\n2) если заложенное имущество возмездно приобретено лицом, которое не знало и не должно было знать, что это имущество является предметом залога;\n\n3) в случае гибели заложенной вещи или прекращения заложенного права, если залогодатель не воспользовался правом, предусмотренным пунктом 2 статьи 345 настоящего Кодекса;\n\n4) в случае реализации заложенного имущества в целях удовлетворения требований залогодержателя в порядке, установленном законом, в том числе при оставлении залогодержателем заложенного имущества за собой, и в случае, если он не воспользовался этим правом (пункт 5 статьи 3502);\n\n5) в случае прекращения договора залога в порядке и по основаниям, которые предусмотрены законом, а также в случае признания договора залога недействительным;\n\n6) по решению суда в случае, предусмотренном пунктом 3 статьи 343 настоящего Кодекса;\n\n7) в случае изъятия заложенного имущества (статьи 167, 327), за исключением случаев, предусмотренных пунктом 1 статьи 353 настоящего Кодекса;\n\n8) в случае реализации заложенного имущества в целях удовлетворения требований предшествующего залогодержателя (пункт 3 статьи 3421);\n\n9) в случаях, указанных в пункте 2 статьи 354 и статье 355 настоящего Кодекса;\n\n10) в иных случаях, предусмотренных законом или договором.\n\n2. При прекращении залога залогодержатель, у которого находилось заложенное имущество, обязан возвратить его залогодателю или иному управомоченному лицу.\n\nЗалогодатель вправе требовать от залогодержателя совершения всех необходимых действий, направленных на внесение записи о прекращении залога (статья 3391).","article_title":"Статья 352. Прекращение залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7bfc85feda8effc870e5643042e2ec92eff1fb552de3a103aa5eef9adba53d5f"},{"code_id":"GK_RF","article_number":"353","version_date":"1994-11-30","article_text":"1. В случае перехода прав на заложенное имущество от залогодателя к другому лицу в результате возмездного или безвозмездного отчуждения этого имущества (за исключением случаев, указанных в подпункте 2 пункта 1 статьи 352 и статье 357 настоящего Кодекса) либо в порядке универсального правопреемства залог сохраняется.\n\nПравопреемник залогодателя приобретает права и несет обязанности залогодателя, за исключением прав и обязанностей, которые в силу закона или существа отношений между сторонами связаны с первоначальным залогодателем.\n\n2. Если имущество залогодателя, являющееся предметом залога, перешло в порядке правопреемства к нескольким лицам, каждый из правопреемников (приобретателей имущества) несет вытекающие из залога последствия неисполнения обеспеченного залогом обязательства соразмерно перешедшей к нему части указанного имущества. Однако если предмет залога неделим или по иным основаниям остается в общей собственности правопреемников, они становятся солидарными залогодателями.","article_title":"Статья 353. Сохранение залога при переходе прав на заложенное имущество к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e2373f4b0345f96b7ccac0fc5ba91471c7dd8e475e56026029ea7c46b39ad95"},{"code_id":"GK_RF","article_number":"354","version_date":"1994-11-30","article_text":"1. Залогодержатель без согласия залогодателя вправе передать свои права и обязанности по договору залога другому лицу с соблюдением правил, установленных главой 24 настоящего Кодекса.\n\n2. Передача залогодержателем своих прав и обязанностей по договору залога другому лицу допускается при условии одновременной уступки тому же лицу права требования к должнику по основному обязательству, обеспеченному залогом. Если иное не предусмотрено законом, при несоблюдении указанного условия залог прекращается.","article_title":"Статья 354. Передача прав и обязанностей по договору залога","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f85eba2fba673cb3dc64a4f14590aa62a1e8ff9dee2ee37fd72d3940de136da"},{"code_id":"GK_RF","article_number":"355","version_date":"1994-11-30","article_text":"С переводом на другое лицо долга по обязательству, обеспеченному залогом, залог прекращается, если иное не предусмотрено соглашением между кредитором и залогодателем.","article_title":"Статья 355. Перевод долга по обязательству, обеспеченному залогом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26a10f210df59cb40d861fcfec6113ab1c871227fef12e4c00f0bd52eeb73d20"},{"code_id":"GK_RF","article_number":"356","version_date":"1994-11-30","article_text":"1. Кредитор (кредиторы) по обеспечиваемому залогом обязательству (обязательствам), исполнение которого связано с осуществлением его сторонами предпринимательской деятельности, вправе заключить договор управления залогом с одним из таких кредиторов или третьим лицом (управляющим залогом).\n\nПо договору управления залогом управляющий залогом, действуя от имени и в интересах всех кредиторов, заключивших договор, обязуется заключить договор залога с залогодателем и (или) осуществлять все права и обязанности залогодержателя по договору залога, а кредитор (кредиторы) - компенсировать управляющему залогом понесенные им расходы и уплатить ему вознаграждение, если иное не предусмотрено договором.\n\nЕсли залог возник ранее заключения договора управления залогом, управляющий залогом по соглашению о передаче договора залога (статья 3923) вправе осуществлять в силу договора управления залогом все права и обязанности залогодержателя.\n\nКредитор (кредиторы) не вправе осуществлять свои права и обязанности залогодержателей до момента прекращения договора управления залогом.\n\nПереход прав кредитора по обеспечиваемому залогом обязательству к другому лицу влечет перемену соответствующего лица в отношениях по договору управления залогом, если иное не предусмотрено законом или договором либо не вытекает из существа обязательства. Договор управления залогом может предусматривать заранее данное согласие управляющего залогом на замену стороны в таком договоре в случае уступки прав по обеспечиваемому залогом обязательству. (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\n2. Управляющим залогом может быть индивидуальный предприниматель или коммерческая организация.\n\n3. Управляющий залогом обязан осуществлять все права и обязанности залогодержателя по договору залога на наиболее выгодных для кредитора (кредиторов) условиях. Полномочия управляющего залогом определяются договором управления залогом (пункт 4 статьи 185) и могут быть изменены по соглашению сторон договора управления залогом.\n\nДоговором управления залогом может быть предусмотрено, что определенные правомочия залогодержателя осуществляются управляющим залогом с предварительного согласия кредитора (кредиторов).\n\n4. Имущество, полученное управляющим залогом в интересах кредиторов, являющихся сторонами договора управления залогом, в том числе в результате обращения взыскания на предмет залога, поступает в долевую собственность указанных кредиторов пропорционально размерам их требований, обеспеченных залогом, если иное не установлено соглашением между кредиторами, и подлежит продаже по требованию любого из кредиторов.\n\nУправляющий залогом обязан вести реестр всех кредиторов, являющихся сторонами договора управления залогом, и оснований возникновения их требований. (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\nЕсли иное не предусмотрено договором управления залогом, денежные средства, получаемые управляющим залогом в результате исполнения договора управления залогом, подлежат зачислению на номинальный счет, который обязан открыть управляющий залогом и бенефициаром (бенефициарами) по которому является кредитор (кредиторы). (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\nВ случае заключения договора синдицированного кредита (займа), обеспеченного залогом, бенефициаром (бенефициарами) по договору номинального счета, указанного в абзаце третьем настоящего пункта, является кредитор (кредиторы), при этом управляющий залогом обязан перечислить денежные средства, поступившие на номинальный счет управляющего залогом, на счет кредитного управляющего в срок, определяемый договором управления залогом. Иной порядок передачи кредитору (кредиторам) причитающихся ему в результате исполнения договора управления залогом денежных средств может быть предусмотрен договором управления залогом. (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\n5. Договор управления залогом прекращается вследствие:\n\n1) прекращения обеспеченного залогом обязательства;\n\n2) расторжения договора по решению кредитора (кредиторов) в одностороннем порядке;\n\n3) признания управляющего залогом несостоятельным (банкротом).\n\n6. В части, не урегулированной настоящей статьей, если иное не вытекает из существа обязательств сторон, к обязанностям управляющего по договору управления залогом, не являющегося залогодержателем, применяются правила о договоре поручения, а к правам и обязанностям залогодержателей по отношению друг к другу применяются правила о договоре простого товарищества, заключаемом для осуществления предпринимательской деятельности.\n\n2. Отдельные виды залога","article_title":"Статья 356. Договор управления залогом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0097fbed5c50ec23461b19ae7486e0fad1e9534167fa310b0ea84634d3db8382"},{"code_id":"GK_RF","article_number":"357","version_date":"1994-11-30","article_text":"1. Залогом товаров в обороте признается залог товаров с оставлением их у залогодателя и с предоставлением залогодателю права изменять состав и натуральную форму заложенного имущества (товарных запасов, сырья, материалов, полуфабрикатов, готовой продукции и т.п.) при условии, что их общая стоимость не становится меньше указанной в договоре залога.\n\nПредмет залога по договору залога товаров в обороте может быть определен посредством указания родовых признаков соответствующих товаров и мест их нахождения в определенных зданиях, помещениях или на земельных участках.\n\nУменьшение стоимости заложенных товаров в обороте допускается соразмерно исполненной части обеспеченного залогом обязательства, если иное не предусмотрено договором.\n\n2. Товары в обороте, отчужденные залогодателем, перестают быть предметом залога с момента их перехода в собственность, хозяйственное ведение или оперативное управление приобретателя, а приобретенные залогодателем товары, которые указаны в договоре залога товаров в обороте, становятся предметом залога с момента возникновения у залогодателя на них права собственности, хозяйственного ведения или оперативного управления.\n\n3. Залогодатель товаров в обороте обязан вести книгу записи залогов, в которую вносятся записи об условиях залога товаров и обо всех операциях, влекущих изменение состава или натуральной формы заложенных товаров, включая их переработку, на день последней операции, если иное не предусмотрено договором залога.\n\n4. При нарушении залогодателем условий залога товаров в обороте залогодержатель вправе приостановить операции с заложенными товарами до устранения нарушения путем наложения на них своих знаков и печатей. В целях различения указанных заложенных товаров и иных вещей может быть нотариально удостоверен факт нахождения заложенных товаров в определенном месте в определенное время.","article_title":"Статья 357. Залог товаров в обороте","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e6851649eb59383f0e0db3153abf30573e49cac42eb1bbd35e8b0d02fcbc770"},{"code_id":"GK_RF","article_number":"358","version_date":"1994-11-30","article_text":"1. Принятие от граждан в залог движимых вещей, предназначенных для личного потребления, в обеспечение краткосрочных займов может осуществляться в качестве предпринимательской деятельности специализированными организациями - ломбардами.\n\n2. Договор займа оформляется выдачей ломбардом залогового билета.\n\n3. Закладываемые вещи передаются в ломбард.\n\nЛомбард обязан страховать в пользу залогодателя за свой счет принятые в залог вещи в полной сумме их оценки, соответствующей ценам на вещи такого рода и такого качества, обычно устанавливаемым в торговле в момент их принятия в залог.\n\nЛомбард не вправе пользоваться и распоряжаться заложенными вещами.\n\n4. Ломбард несет ответственность за утрату з\n\nаложенных вещей и их повреждение, если не докажет, что утрата, повреждение произошли вследствие непреодолимой силы.\n\n5. В случае невозвращения в установленный срок суммы займа, обеспеченного залогом вещей в ломбарде, ломбард по истечении льготного месячного срока вправе продать это имущество в порядке, установленном законом о ломбардах. После этого требования ломбарда к залогодателю (должнику) погашаются, даже если сумма, вырученная при реализации заложенного имущества, недостаточна для их полного удовлетворения.\n\n6. Правила кредитования граждан ломбардами под залог принадлежащих гражданам вещей устанавливаются законом о ломбардах в соответствии с настоящим Кодексом.\n\n7. Условия договора займа, ограничивающие права залогодателя по сравнению с правами, предоставляемыми ему настоящим Кодексом и другими законами, ничтожны. Вместо таких условий применяются соответствующие положения закона.","article_title":"Статья 358. Залог вещей в ломбарде","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f93d1dd00fde57feeb2f9373cae6db4f4deaa1161147e6843b67458d5cdac751"},{"code_id":"GK_RF","article_number":"358.1","version_date":"1994-11-30","article_text":"1. Предметом залога могут быть имущественные права (требования), вытекающие из обязательства залогодателя. Залогодателем права может быть лицо, являющееся кредитором в обязательстве, из которого вытекает закладываемое право (правообладатель).\n\nЕсли законом или договором залога права не установлено иное, предметом залога являются все принадлежащие залогодателю права, которые вытекают из соответствующего обязательства и могут быть предметом залога.\n\n2. Предметом залога может быть право, которое возникнет в будущем из существующего или будущего обязательства.\n\n3. Если иное не установлено законом или договором либо не следует из существа обязательства, предметом залога могут быть часть требования, отдельное требование или несколько требований, вытекающих из договора или иного обязательства.\n\n4. Предметом залога по одному договору залога может быть совокупность прав (требований), каждое из которых вытекает из самостоятельного обязательства, в том числе совокупность будущих прав, а также совокупность существующих и будущих прав.\n\n5. Если заложенное право прекратилось в связи с окончанием срока его действия до обращения на него взыскания залогодержателем, залогодержатель не вправе требовать досрочного исполнения основного обязательства, исполнение которого было обеспечено залогом этого права.\n\n6. В случаях, установленных законом или договором, при обращении взыскания на заложенное право и реализации заложенного права к его приобретателю вместе с этим правом переходят связанные с ним обязанности.","article_title":"Статья 358.1. Залог обязательственных прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5d1f9ff235e479508f16fed6a930e0bb856e55fb3837fba665f9ee4cd71ff65e"},{"code_id":"GK_RF","article_number":"358.10","version_date":"1994-11-30","article_text":"1. В договоре залога прав по договору банковского счета должны быть указаны банковские реквизиты залогового счета, существо, размер и срок исполнения обязательства, обеспечиваемого залогом прав по договору банковского счета.\n\n2. Если иное не предусмотрено договором залога прав по договору банковского счета, договор считается заключенным с условием о залоге прав в отношении всей денежной суммы, находящейся на залоговом счете в любой момент в течение времени действия договора.\n\n3. Договором залога прав по договору банковского счета может быть предусмотрено, что предметом залога являются права залогодателя по договору банковского счета в отношении твердой денежной суммы, размер которой указан в договоре залога. В этом случае размер денежных средств на счете залогодателя в любой момент в течение времени действия договора залога не должен быть ниже определенной договором суммы.\n\nЕсли иное не предусмотрено договором залога, уменьшение размера твердой денежной суммы, в отношении которой заложены права залогодателя по договору банковского счета, соразмерно исполненной части обеспеченного залогом обязательства не допускается.","article_title":"Статья 358.10. Содержание договора залога прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a9a6b70671404122d90c0eee9597ca13f685825098caf68c0b531648397e363"},{"code_id":"GK_RF","article_number":"358.11","version_date":"1994-11-30","article_text":"Залог на основании договора залога прав по договору банковского счета возникает с момента уведомления банка о залоге прав и предоставления ему копии договора залога. В случае, если залогодержателем является банк, заключивший с клиентом (залогодателем) договор залогового счета, залог возникает с момента заключения договора залога прав по банковскому счету.","article_title":"Статья 358.11. Возникновение залога прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bf68a39ee31902bfc75129cecb3fd614958f8aae63aa400aa1b49f42194dd86"},{"code_id":"GK_RF","article_number":"358.12","version_date":"1994-11-30","article_text":"1. Залогодатель вправе распоряжаться свободно денежными средствами на залоговом счете, если иное не предусмотрено договором залога прав по соответствующему договору банковского счета или правилами настоящей статьи.\n\nБанк обязан проводить операции по залоговому счету в соответствии с правилами настоящего параграфа и иными правилами настоящего Кодекса, другими законами и банковскими правилами, а в части, ими не урегулированной, в соответствии с соглашением, заключенным между банком, залогодателем и залогодержателем.\n\n2. Банк по требованию залогодержателя, предъявленному в письменной форме, обязан предоставлять ему сведения об остатке денежных средств на залоговом счете, об операциях по указанному счету и о предъявленных по счету требованиях, а также о запретах и об ограничениях, наложенных на указанный счет. Порядок и сроки предоставления банком таких сведений залогодержателю определяются банковскими правилами, а в части, ими не урегулированной, соглашением, заключенным между банком, залогодателем и залогодержателем.\n\n3. При заключении договора залога прав залогодателя по договору банковского счета в отношении твердой денежной суммы залогодатель без согласия в письменной форме залогодержателя не вправе давать банку распоряжения, в результате исполнения которых сумма денежных средств на залоговом счете станет ниже указанной твердой денежной суммы, а банк не вправе исполнять такие распоряжения.\n\n4. После получения банком уведомления в письменной форме залогодержателя о неисполнении или ненадлежащем исполнении должником обеспеченного залогом обязательства банк не вправе исполнять распоряжения залогодателя, в результате исполнения которых сумма денежных средств на залоговом счете станет ниже суммы, эквивалентной размеру обеспеченного обязательства, указанному в договоре залога.\n\n5. Банк, нарушивший обязанности, указанные в пунктах 3 и 4 настоящей статьи, несет перед залогодержателем в пределах денежных сумм, списанных с залогового счета во исполнение распоряжения клиента (залогодателя), солидарную с ним ответственность.","article_title":"Статья 358.12. Распоряжение банковским счетом, права по которому заложены","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"97936d2188dba24dfc1bf20f8d46abf6be879070c9b6430b4c09170744022741"},{"code_id":"GK_RF","article_number":"358.13","version_date":"1994-11-30","article_text":"Без согласия залогодержателя стороны договора банковского счета, права по которому заложены, не вправе вносить в него изменения, а также совершать действия, влекущие прекращение такого договора.","article_title":"Статья 358.13. Изменение и прекращение договора залога прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d6964cf87c02a4760c95067bfe4056330e958c5ec6ed87573a7aab0ea28ccce3"},{"code_id":"GK_RF","article_number":"358.14","version_date":"1994-11-30","article_text":"1. При обращении взыскания на заложенные права по договору банковского счета в соответствии со статьей 349 настоящего Кодекса в судебном или во внесудебном порядке требования залогодержателя удовлетворяются путем списания банком на основании распоряжения залогодержателя денежных средств с залогового счета залогодателя и выдачи их залогодержателю или зачисления их на счет, указанный залогодержателем (пункт 2 статьи 854). Правила о реализации заложенного имущества, установленные статьями 350 - 3502 настоящего Кодекса, в этих случаях не применяются.","article_title":"Статья 358.14. Реализация заложенных прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33c1f5aca2b99572968ec4c0c69087150b49e197970eceedd9a2be02b2c87092"},{"code_id":"GK_RF","article_number":"358.15","version_date":"1994-11-30","article_text":"1. Залог прав акционера осуществляется посредством залога принадлежащих акционеру акций этого общества, залог прав участника общества с ограниченной ответственностью - посредством залога принадлежащей ему доли в уставном капитале общества в соответствии с правилами, установленными настоящим Кодексом и законами о хозяйственных обществах.\n\nЗалог прав участников (учредителей) иных юридических лиц не допускается.\n\n2. При залоге акций удостоверенные ими права осуществляет залогодатель (акционер), если иное не предусмотрено договором залога акций (статья 35817).\n\nЕсли иное не предусмотрено договором залога доли в уставном капитале общества с ограниченной ответственностью, до момента прекращения залога права участника общества осуществляются залогодержателем.","article_title":"Статья 358.15. Залог прав участников юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37efdc4ad964bacf06e183cf0f63c439ee642fb7980931fdfd8fc43871723fd8"},{"code_id":"GK_RF","article_number":"358.16","version_date":"1994-11-30","article_text":"1. Залог документарной ценной бумаги возникает с момента передачи ее залогодержателю, если иное не установлено законом или договором.\n\nЗалог бездокументарной ценной бумаги возникает с момента внесения записи о залоге по счету, на котором учитываются права владельца бездокументарных ценных бумаг, или в случаях, установленных законом, по счету иного лица, если законом или договором не установлено, что залог возникает позднее.\n\n2. Если залог ордерной ценной бумаги совершен посредством залогового индоссамента, правоотношения между залогодателем, залогодержателем и должником по ордерной ценной бумаге регулируются законами о ценных бумагах.\n\n3. К отношениям, связанным с залогом документарных ценных бумаг и не урегулированным настоящей статьей, статьей 35817 настоящего Кодекса или другими законами, применяются правила о залоге вещей, если иное не установлено законами о ценных бумагах и не вытекает из существа соответствующих ценных бумаг.\n\n4. К отношениям, связанным с залогом бездокументарных ценных бумаг и не урегулированным настоящей статьей, статьей 35817 настоящего Кодекса или другими законами, применяются правила о залоге документарных бумаг, если иное не вытекает из существа соответствующих бездокументарных ценных бумаг.","article_title":"Статья 358.16. Залог ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ac84d882716230c633456f85d5dfa78bed6b6321b30d79d4a9b606801662a35"},{"code_id":"GK_RF","article_number":"358.17","version_date":"1994-11-30","article_text":"Если договором залога залогодержатель ограничен в осуществлении прав, удостоверенных ценной бумагой, нарушение им таких ограничений не затрагивает права и обязанности третьих лиц, которые не знали и не должны были знать о таких ограничениях. Однако залогодержатель несет перед залогодателем ответственность за данные нарушения, предусмотренную законом и договором, а залогодатель вправе требовать в судебном порядке прекращения права залога.\n\nудостоверенных заложенной ценной бумагой, в случае нарушения залогодателем указанной обязанности он несет перед залогодержателем ответственность, предусмотренную законом и договором, а залогодержатель вправе требовать досрочного исполнения обеспеченного залогом обязательства.\n\nЕсли в соответствии с законом залогодатель ценных бумаг в силу того, что он является их владельцем, дополнительно к ним безвозмездно получает иные ценные бумаги или иное имущество, такие ценные бумаги или такое имущество находятся в залоге у залогодержателя (пункт 3 статьи 336).","article_title":"Статья 358.17. Осуществление прав, удостоверенных заложенной ценной бумагой","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51b1ea01383fd16a65d48669b29f19df6c6adbb1c08c24dc7f76186aa163b534"},{"code_id":"GK_RF","article_number":"358.18","version_date":"1994-11-30","article_text":"1. Исключительные права на результаты интеллектуальной деятельности и приравненные к ним средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий (пункт 1 статьи 1225) могут быть предметом залога в той мере, в какой правила настоящего Кодекса допускают их отчуждение.\n\n2. Государственная регистрация залога исключительных прав осуществляется в соответствии с правилами раздела VII настоящего Кодекса.\n\n3. К договору залога исключительного права на результат интеллектуальной деятельности или на средство индивидуализации применяются общие положения о залоге (статьи 334 - 356), а к договору залога прав по договору об отчуждении исключительных прав и по лицензионному (сублицензионному) договору применяются положения о залоге обязательственных прав (статьи 3581 - 3588), поскольку иное не установлено настоящим Кодексом и не вытекает из содержания или характера соответствующих прав.\n\n4. По договору залога исключительного права на результат интеллектуальной деятельности или на средство индивидуализации залогодатель в течение срока действия этого договора без согласия залогодержателя вправе использовать такой результат интеллектуальной деятельности или такое средство индивидуализации и распоряжаться исключительным правом на такой результат или на такое средство, за исключением случая отчуждения исключительного права, если договором не предусмотрено иное. Залогодатель не вправе отчуждать исключительное право без согласия залогодержателя, если иное не предусмотрено договором.\n\n(Дополнение статьей - Федеральный закон от 12.03.2014 № 35-ФЗ)\n\n(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 358.18. Залог исключительных прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"486b7988fdd6d59e5f2a2d380f4c21a7135700f93327de37e0fd55ca0926fb9a"},{"code_id":"GK_RF","article_number":"358.2","version_date":"1994-11-30","article_text":"1. Залог права не требует согласия должника правообладателя, за исключением случаев, предусмотренных законом или соглашением между правообладателем и его должником.\n\n2. В случаях, когда соглашением между правообладателем и его должником уступка права запрещена или невозможность уступки права вытекает из существа обязательства, залог права не допускается, если законом не установлено иное.\n\n3. Залог права допускается только с согласия должника правообладателя в случаях, если:\n\n1) в силу закона или соглашения между правообладателем и его должником для уступки права (требования) необходимо согласие должника;\n\n2) при обращении взыскания на заложенное право и его реализации к приобретателю права должны перейти связанные с заложенным правом обязанности (пункт 6 статьи 3581).\n\n4. Если иное не предусмотрено законом, нарушение правообладателем указанного в договоре с должником, связанном с осуществлением его сторонами предпринимательской деятельности, ограничения по уступке или залогу права (требования) влечет последствия, предусмотренные пунктом 3 статьи 388 настоящего Кодекса.","article_title":"Статья 358.2. Ограничения залога права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"18ac8b1a5d38a162dbf51ef83bbc4ab57fee0d9908d6272484427f09abb972ea"},{"code_id":"GK_RF","article_number":"358.3","version_date":"1994-11-30","article_text":"1. В договоре залога права наряду с условиями, предусмотренными статьей 339 настоящего Кодекса, должны быть указаны обязательство, из которого вытекает закладываемое право, сведения о должнике залогодателя и сторона договора залога, у которой находятся подлинники документов, удостоверяющих закладываемое право.\n\nВ случае, если предметом залога является принадлежащее залогодателю право требовать уплаты денежной суммы, в договоре залога может быть указан размер этой суммы или порядок ее определения.\n\nЕсли в договоре залога не указано, что подлинники документов, удостоверяющих закладываемое право, остаются у залогодателя или передаются нотариусу на хранение, залогодатель обязан передать такие подлинники в срок, указанный в договоре залога, или, если договором указанный срок не установлен, в разумный срок залогодержателю по его требованию, предъявленному в письменной форме. Соглашением между залогодателем и залогодержателем может быть предусмотрено, что документы передаются на хранение третьему лицу.\n\nПри залоге права, если иное не предусмотрено законом или договором, обязанности, предусмотренные статьей 343 настоящего Кодекса, возлагаются на сторону договора залога, у которой находятся подлинники документов, удостоверяющих заложенное право.\n\n2. В случаях, если предметом залога является совокупность прав (требований) или будущее право (пункты 2 и 4 статьи 3581), сведения об обязательстве, из которого вытекает закладываемое право, и о должнике залогодателя могут быть указаны в договоре общим образом, то есть посредством данных, позволяющих индивидуализировать закладываемые права и определить лиц, которые являются или на момент обращения взыскания на предмет залога будут являться должниками по этим правам.","article_title":"Статья 358.3. Содержание договора залога права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"634b90f5e1719157add6dde62a7a98815bf6182e97625b5a02bfb0ae6f266e50"},{"code_id":"GK_RF","article_number":"358.4","version_date":"1994-11-30","article_text":"В случае залога прав уведомление должника по обязательству, права по которому закладываются, осуществляется по правилам статьи 385 настоящего Кодекса.","article_title":"Статья 358.4. Уведомление должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"18254405fc78adc2c3609b1c08f6044cab2cec0e1aa7330bddf75402058367f6"},{"code_id":"GK_RF","article_number":"358.5","version_date":"1994-11-30","article_text":"1. Залог права возникает с момента заключения договора залога, а при залоге будущего права с момента возникновения этого права.\n\n2. Если залогом права обеспечено исполнение обязательства, которое возникнет в будущем, залог права возникает с момента возникновения этого обязательства.","article_title":"Статья 358.5. Возникновение залога права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6cb32fab38842138e1ecfdda4d96bf47c343da69e15941eb8ec79c9490a7a4f6"},{"code_id":"GK_RF","article_number":"358.6","version_date":"1994-11-30","article_text":"1. Должник залогодателя, право требования к которому заложено, исполняет соответствующее обязательство залогодателю, если договором залога не предусмотрено иное.\n\nЕсли договором залога предусмотрено право залогодержателя получить исполнение от должника по обязательству, право по которому заложено, должник, уведомленный об этом (статья 3584), обязан исполнять свое обязательство залогодержателю или указанному им лицу.\n\n2. Если иное не установлено договором залога, при получении от своего должника в счет исполнения обязательства денежных сумм залогодатель по требованию залогодержателя обязан уплатить ему соответствующие суммы в счет исполнения обязательства, обеспеченного залогом.\n\nЕсли иное не предусмотрено договором залога, денежные суммы, полученные залогодержателем от должника залогодателя по заложенному праву (требованию), засчитываются в погашение обязательства, в обеспечение исполнения которого заложено соответствующее право.\n\n3. После возникновения оснований для обращения взыскания на заложенное право требования залогодержатель имеет право на получение исполнения по данному требованию в пределах, необходимых для покрытия требований залогодержателя, обеспеченных залогом, в том числе право на подачу заявлений об исполнении обязательств до востребования, если предметом залога является требование по обязательству до востребования.\n\n4. Законом или договором залога права может быть предусмотрено, что денежные суммы, полученные залогодателем от его должника в счет исполнения обязательства, право (требование) по которому заложено, зачисляются на залоговый счет залогодателя. К такому счету применяются правила о договоре залога прав по договору банковского счета.","article_title":"Статья 358.6. Исполнение обязательства должником залогодателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"498d3f99f7f5854aa0427ab849bbf65dace7d5085fc490fbe1cb29a2fb62bd46"},{"code_id":"GK_RF","article_number":"358.7","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором, в случае нарушения обязанностей, предусмотренных статьей 3586 настоящего Кодекса, залогодержатель вправе требовать от залогодателя досрочного исполнения обеспеченного залогом обязательства, а при его неисполнении - обратить взыскание на предмет залога в установленном порядке.\n\n2. Залогодержатель вправе принимать самостоятельно меры, необходимые для защиты заложенного права от нарушений со стороны третьих лиц.","article_title":"Статья 358.7. Защита залогодержателя права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61aa8e5a73eda37cfcc8aae9348af06a83bc0dd2384c2a1b29ee58ccbf923f9e"},{"code_id":"GK_RF","article_number":"358.8","version_date":"1994-11-30","article_text":"1. Реализация заложенного права осуществляется в порядке, установленном пунктом 1 статьи 350 и пунктом 1 статьи 3501 настоящего Кодекса.\n\n2. В случае обращения взыскания на заложенное право в судебном порядке стороны могут договориться о том, что его реализация осуществляется посредством перевода по требованию залогодержателя заложенного права на залогодержателя по решению суда.\n\n3. Если взыскание на заложенное право обращается во внесудебном порядке, стороны могут договориться, что реализация заложенного права осуществляется посредством уступки заложенного права залогодателем залогодержателю или указанному залогодержателем третьему лицу. В случае отказа залогодателя уступить заложенное право залогодержатель или третье лицо вправе требовать перевода на себя этого права по решению суда или на основании исполнительной надписи нотариуса и возмещения убытков, причиненных в связи с отказом уступить это право.\n\n4. С момента перехода заложенного права к залогодержателю или указанному им третьему лицу обязательство, исполнение которого обеспечено залогом этого права, прекращается в размере, эквивалентном стоимости (начальной продажной цене) заложенного права (пункт 7 статьи 349).\n\nПравила настоящего пункта применяются, если соглашением залогодателя с залогодержателем, а также с должником по обязательству, обеспеченному залогом права, когда залогодателем является третье лицо, не предусмотрено иное.","article_title":"Статья 358.8. Порядок реализации заложенного права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cff3cd2944aae4221c35aa6fa17c859710883ce19ae27d7f162adf1f9dd97e45"},{"code_id":"GK_RF","article_number":"358.9","version_date":"1994-11-30","article_text":"1. Предметом залога могут быть права по договору банковского счета при условии открытия банком клиенту залогового счета.\n\n2. Залогодержателем при залоге прав по договору банковского счета может быть, в частности, банк, заключивший с клиентом (залогодателем) договор залогового счета.\n\n3. Залоговый счет может быть открыт банком клиенту независимо от заключения на момент его открытия договора залога прав по договору банковского счета.\n\n4. Договор залога прав по договору банковского счета может быть заключен также при отсутствии на момент его заключения у клиента денежных средств на залоговом счете.\n\n5. Договором залога имущества иного, чем права по договору банковского счета, может быть предусмотрено, что причитающиеся залогодателю денежные суммы (страховое возмещение за утрату или повреждение заложенного имущества, доходы от использования заложенного имущества, денежные суммы, подлежащие уплате залогодателю в счет исполнения обязательства, право (требование) по которому заложено, и т.п.) зачисляются на залоговый счет.\n\n6. Удостоверение обязательства банка по заключенному с клиентом договору об открытии залогового счета выдачей банком ценной бумаги не допускается.\n\n7. Если иное не предусмотрено настоящей статьей и статьями 35810 - 35814 настоящего Кодекса, к договору об открытии залогового счета применяются правила главы 45 настоящего Кодекса.\n\n8. Правила настоящего Кодекса о залоге прав по договору банковского счета (настоящая статья и статьи 35810 - 35814) соответственно применяются к залогу прав по договору банковского вклада.","article_title":"Статья 358.9. Основные положения о залоге прав по договору банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c44a72f0776f2255b21b7249cf1c094a3223fc253840b85b4cea0546f1a088fc"},{"code_id":"GK_RF","article_number":"359","version_date":"1994-11-30","article_text":"1. Кредитор, у которого находится вещь, подлежащая передаче должнику либо лицу, указанному должником, вправе в случае неисполнения должником в срок обязательства по оплате этой вещи или возмещению кредитору связанных с нею издержек и других убытков удерживать ее до тех пор, пока соответствующее обязательство не будет исполнено.\n\nУдержанием вещи могут обеспечиваться также требования, хотя и не связанные с оплатой вещи или возмещением издержек на нее и других убытков, но возникшие из обязательства, стороны которого действуют как предприниматели.\n\n2. Кредитор может удерживать находящуюся у него вещь, несмотря на то, что после того, как эта вещь поступила во владение кредитора, права на нее приобретены третьим лицом.\n\n3. Правила настоящей статьи применяются, если договором не предусмотрено иное.","article_title":"Статья 359. Основания удержания","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1da7a5102b316d77e12366596a47cdbd99eb48cc163342ea322069da2a8bc67"},{"code_id":"GK_RF","article_number":"36","version_date":"1994-11-30","article_text":"1. Обязанности по опеке и попечительству исполняются безвозмездно, кроме случаев, предусмотренных законом.\n\n2. Опекуны и попечители несовершеннолетних граждан обязаны проживать совместно со своими подопечными. Раздельное проживание попечителя с подопечным, достигшим шестнадцати лет, допускается с разрешения органа опеки и попечительства при условии, что это не отразится неблагоприятно на воспитании и защите прав и интересов подопечного.\n\nОпекуны и попечители обязаны извещать органы опеки и попечительства о перемене места жительства.\n\n3. Опекуны и попечители обязаны заботиться о содержании своих подопечных, об обеспечении их уходом и лечением, защищать их права и интересы.\n\nОпекуны и попечители несовершеннолетних должны заботиться об их обучении и воспитании.\n\nОпекуны и попечители заботятся о развитии (восстановлении) способности гражданина, дееспособность которого ограничена вследствие психического расстройства, или гражданина, признанного недееспособным, понимать значение своих действий или руководить ими. (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\nОпекуны и попечители исполняют свои функции, учитывая мнение подопечного, а при невозможности его установления - с учетом информации о предпочтениях подопечного, полученной от его родителей, прежних опекунов, иных лиц, оказывавших ему услуги и добросовестно исполнявших свои обязанности. (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\nЕсли основания, в силу которых гражданин, который вследствие психического расстройства может понимать значение своих действий или руководить ими при помощи других лиц, был ограничен в дееспособности, изменились, попечитель обязан обратиться в суд с заявлением об отмене ограничения дееспособности подопечного или о признании его недееспособным в соответствии с пунктом 3 статьи 30 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 36. Исполнение опекунами и попечителями своих обязанностей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69b841d0148e7838e3348d0870766a7f38a927eb2b9ae5266e0b6819a74effef"},{"code_id":"GK_RF","article_number":"360","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\nТребования кредитора, удерживающего вещь, удовлетворяются из ее стоимости в объеме и порядке, предусмотренных для удовлетворения требований, обеспеченных залогом.","article_title":"Статья 360. Удовлетворение требований за счет удерживаемой вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f317284749664e33cbb4d0efbde050a79470bbc026ff8cf350a739f44eee066"},{"code_id":"GK_RF","article_number":"361","version_date":"1994-11-30","article_text":"1. По договору поручительства поручитель обязывается перед кредитором другого лица отвечать за исполнение последним его обязательства полностью или в части. Договор поручительства может быть заключен в обеспечение как денежных, так и неденежных обязательств, а также в обеспечение обязательства, которое возникнет в будущем.\n\n2. Поручительство может возникать на основании закона при наступлении указанных в нем обстоятельств. Правила настоящего Кодекса о поручительстве в силу договора применяются к поручительству, возникающему на основании закона, если законом не установлено иное.\n\n3. Условия поручительства, относящиеся к основному обязательству, считаются согласованными, если в договоре поручительства имеется отсылка к договору, из которого возникло или возникнет в будущем обеспечиваемое обязательство. В договоре поручительства, поручителем по которому является лицо, осуществляющее предпринимательскую деятельность, может быть указано, что поручительство обеспечивает все существующие и (или) будущие обязательства должника перед кредитором в пределах определенной суммы.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 361. Основания возникновения поручительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a7ea752f5a82de7d2f348c418de8249f01ea8f20fca9f3a680582fb3f2fbf91"},{"code_id":"GK_RF","article_number":"362","version_date":"1994-11-30","article_text":"Договор поручительства должен быть совершен в письменной форме. Несоблюдение письменной формы влечет недействительность договора поручительства.","article_title":"Статья 362. Форма договора поручительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad47a42d6be1ef1196c3711e4e7c7885efe481e89411fe1664cd9fbdc8c15985"},{"code_id":"GK_RF","article_number":"363","version_date":"1994-11-30","article_text":"1. При неисполнении или ненадлежащем исполнении должником обеспеченного поручительством обязательства поручитель и должник отвечают перед кредитором солидарно, если законом или договором поручительства не предусмотрена субсидиарная ответственность поручителя.\n\n2. Поручитель отвечает перед кредитором в том же объеме, как и должник, включая уплату процентов, возмещение судебных издержек по взысканию долга и других убытков кредитора, вызванных неисполнением или ненадлежащим исполнением обязательства должником, если иное не предусмотрено договором поручительства.","article_title":"Статья 363. Ответственность поручителя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3547976595ed13e9580ddfcea132fdd94a1810237774234b811ee1aa2f85f5e7"},{"code_id":"GK_RF","article_number":"365","version_date":"1994-11-30","article_text":"1. К поручителю, исполнившему обязательство, переходят права кредитора по этому обязательству и права, принадлежавшие кредитору как залогодержателю, в том объеме, в котором поручитель удовлетворил требование кредитора. Поручитель также вправе требовать от должника уплаты процентов на сумму, выплаченную кредитору, и возмещения иных убытков, понесенных в связи с ответственностью за должника.\n\n2. По исполнении поручителем обязательства кредитор обязан вручить поручителю документы, удостоверяющие требование к должнику, и передать права, обеспечивающие это требование.\n\n3. Правила, установленные настоящей статьей, применяются, если иное не предусмотрено законом, иными правовыми актами или договором поручителя с должником и не вытекает из отношений между ними.","article_title":"Статья 365. Права поручителя, исполнившего обязательство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"297acfe64095c5f56baa8a9d55a04255d2dd48521b3d2fdaa30bf45d049e76be"},{"code_id":"GK_RF","article_number":"366","version_date":"1994-11-30","article_text":"1. Должник, извещенный поручителем о предъявленном к нему кредитором требовании или привлеченный поручителем к участию в деле, обязан сообщить поручителю обо всех имеющихся у него возражениях против этого требования и предоставить имеющиеся у него в подтверждение этих требований доказательства. В противном случае должник лишается права выдвигать возражения, которые могли быть заявлены против требования кредитора, против требования поручителя (пункт 1 статьи 365), если иное не предусмотрено соглашением между поручителем и должником.\n\n2. Должник, исполнивший обязательство, обеспеченное поручительством, обязан известить об этом поручителя немедленно. В противном случае поручитель, в свою очередь исполнивший свое обязательство, вправе взыскать с кредитора неосновательно полученное или предъявить регрессное требование к должнику. В последнем случае должник вправе взыскать с кредитора лишь неосновательно полученное.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 366. Извещения при поручительстве","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b20b35c5ae604f228f29655b15d0ff15ed4db02da5d7ec3059dc1339e90f1c27"},{"code_id":"GK_RF","article_number":"367","version_date":"1994-11-30","article_text":"1. Поручительство прекращается с прекращением обеспеченного им обязательства. Прекращение обеспеченного обязательства в связи с ликвидацией должника после того, как кредитор предъявил в суд или в ином установленном законом порядке требование к поручителю, не прекращает поручительство.\n\nЕсли основное обязательство обеспечено поручительством в части, частичное исполнение основного обязательства засчитывается в счет его необеспеченной части.\n\nЕсли между должником и кредитором существует несколько обязательств, только одно из которых обеспечено поручительством, и должник не указал, какое из обязательств он исполняет, считается, что им исполнено необеспеченное обязательство.\n\n2. В случае, если обеспеченное поручительством обязательство было изменено без согласия поручителя, что повлекло за собой увеличение ответственности или иные неблагоприятные последствия для поручителя, поручитель отвечает на прежних условиях.\n\nДоговор поручительства может предусматривать заранее данное согласие поручителя в случае изменения обязательства отвечать перед кредитором на измененных условиях. Такое согласие должно предусматривать пределы, в которых поручитель согласен отвечать по обязательствам должника.\n\n3. Поручительство прекращается с переводом на другое лицо долга по обеспеченному поручительством обязательству, если поручитель в разумный срок после направления ему уведомления о переводе долга не согласился отвечать за нового должника.\n\nСогласие поручителя отвечать за нового должника должно быть явно выраженным и должно позволять установить круг лиц, при переводе долга на которых поручительство сохраняет силу.\n\n4. Смерть должника, реорганизация юридического лица-должника не прекращают поручительство.\n\n5. Поручительство прекращается, если кредитор отказался принять надлежащее исполнение, предложенное должником или поручителем.\n\n6. Поручительство прекращается по истечении указанного в договоре поручительства срока, на который оно дано. Если такой срок не установлен, оно прекращается при условии, что кредитор в течение года со дня наступления срока исполнения обеспеченного поручительством обязательства не предъявит иск к поручителю. Когда срок исполнения основного обязательства не указан и не может быть определен или определен моментом востребования, поручительство прекращается, если кредитор не предъявит иск к поручителю в течение двух лет со дня заключения договора поручительства.\n\nПредъявление кредитором к должнику требования о досрочном исполнении обязательства не сокращает срок действия поручительства, определяемый исходя из первоначальных условий основного обязательства.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\n(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 367. Прекращение поручительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"573a08b415364e72d87637edbdbe89deced86035052eefc1ce0796a3b3906de7"},{"code_id":"GK_RF","article_number":"368","version_date":"1994-11-30","article_text":"1. По независимой гарантии гарант принимает на себя по просьбе другого лица (принципала) обязательство уплатить указанному им третьему лицу (бенефициару) определенную денежную сумму в соответствии с условиями данного гарантом обязательства независимо от действительности обеспечиваемого такой гарантией обязательства. Требование об определенной денежной сумме считается соблюденным, если условия независимой гарантии позволяют установить подлежащую выплате денежную сумму на момент исполнения обязательства гарантом.\n\n2. Независимая гарантия выдается в письменной форме (пункт 2 статьи 434), позволяющей достоверно определить условия гарантии и удостовериться в подлинности ее выдачи определенным лицом в порядке, установленном законодательством, обычаями или соглашением гаранта с бенефициаром.\n\n3. Независимые гарантии могут выдаваться банками или иными кредитными организациями (банковские гарантии), а также другими коммерческими организациями.\n\nК обязательствам лиц, не указанных в абзаце первом настоящего пункта и выдавших независимую гарантию, применяются правила о договоре поручительства.\n\n4. В независимой гарантии должны быть указаны:\n\nдата выдачи;\n\nпринципал;\n\nбенефициар;\n\nосновное обязательство, исполнение по которому обеспечивается гарантией;\n\nденежная сумма, подлежащая выплате, или порядок ее определения;\n\nсрок действия гарантии;\n\nобстоятельства, при наступлении которых должна быть выплачена сумма гарантии.\n\nВ независимой гарантии может содержаться условие об уменьшении или увеличении суммы гарантии при наступлении определенного срока или определенного события.\n\n5. Правила настоящего параграфа применяются также в случаях, когда обязательство лица, предоставившего обеспечение, состоит в передаче акций, облигаций или вещей, определенных родовыми признаками, если иное не вытекает из существа отношений.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 368. Понятие и форма независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44c517347282b0704b4075bd986de1a82c58762dc80116727a0579875fbf07c7"},{"code_id":"GK_RF","article_number":"369","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 369. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca90085597fc0f29c91e6a270b419228a61499115e0d30be41e77deb80417b2b"},{"code_id":"GK_RF","article_number":"37","version_date":"1994-11-30","article_text":"Порядок управления имуществом подопечного определяется Федеральным законом \"Об опеке и попечительстве\". (В редакции Федерального закона от 24.04.2008 № 49-ФЗ)","article_title":"Статья 37. Распоряжение имуществом подопечного","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2df459b1ef3f5c0d6d00dcc7057be583e3c7cd7bbaaaf789b5113b9189d7152c"},{"code_id":"GK_RF","article_number":"370","version_date":"1994-11-30","article_text":"1. Предусмотренное независимой гарантией обязательство гаранта перед бенефициаром не зависит в отношениях между ними от основного обязательства, в обеспечение исполнения которого она выдана, от отношений между принципалом и гарантом, а также от каких-либо других обязательств, даже если в независимой гарантии содержатся ссылки на них.\n\n2. Гарант не вправе выдвигать против требования бенефициара возражения, вытекающие из основного обязательства, в обеспечение исполнения которого независимая гарантия выдана, а также из какого-либо иного обязательства, в том числе из соглашения о выдаче независимой гарантии, и в своих возражениях против требования бенефициара об исполнении независимой гарантии не вправе ссылаться на обстоятельства, не указанные в гарантии.\n\n3. Гарант не вправе предъявлять бенефициару к зачету требование, уступленное гаранту принципалом, если иное не предусмотрено независимой гарантией или соглашением гаранта с бенефициаром.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 370. Независимость гарантии от иных обязательств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cef0c236be41a6919b32801afda28206460bc9c330ed5dee749b417f2c9ad708"},{"code_id":"GK_RF","article_number":"371","version_date":"1994-11-30","article_text":"1. Независимая гарантия не может быть отозвана или изменена гарантом, если в ней не предусмотрено иное.\n\n2. В случаях, когда по условиям независимой гарантии допускается ее отзыв или изменение гарантом, такой отзыв или такое изменение производится в форме, в которой выдана гарантия, если иная форма не предусмотрена гарантией.\n\n3. Если по условиям независимой гарантии допускается возможность ее отзыва или изменения гарантом с согласия бенефициара, то обязательство гаранта считается измененным или прекращенным с момента получения гарантом согласия бенефициара.\n\n4. Изменение обязательства гаранта после выдачи независимой гарантии принципалу не затрагивает прав и обязанностей принципала, если он впоследствии не дал согласие на соответствующее изменение.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 371. Отзыв и изменение независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"605b657e9b379fa15182a258bc89938df923d3e7bd54f20577e27407c5c1b89a"},{"code_id":"GK_RF","article_number":"372","version_date":"1994-11-30","article_text":"1. Бенефициар по независимой гарантии не вправе передавать другому лицу право требования к гаранту, если в гарантии не предусмотрено иное.\n\nПередача бенефициаром прав по независимой гарантии другому лицу допускается лишь при условии одновременной уступки тому же лицу прав по основному обязательству.\n\n2. В случае, когда по условиям независимой гарантии допускается передача бенефициаром права требования к гаранту, такая передача возможна лишь с согласия гаранта, если в гарантии не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 372. Передача прав по независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9219ff52a6b87ba978a8d2c22cab3cc23feafaf3528f8b44f08d35f26dac8606"},{"code_id":"GK_RF","article_number":"373","version_date":"1994-11-30","article_text":"Независимая гарантия вступает в силу с момента ее отправки (передачи) гарантом, если в гарантии не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 373. Вступление независимой гарантии в силу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ecb9f8699112add0ac30492896376b37c8ff82fdcf0153a41dff74cfdd4cbdf"},{"code_id":"GK_RF","article_number":"374","version_date":"1994-11-30","article_text":"1. Требование бенефициара об уплате денежной суммы по независимой гарантии должно быть представлено в письменной форме гаранту с приложением указанных в гарантии документов. В требовании или в приложении к нему бенефициар должен указать обстоятельства, наступление которых влечет выплату по независимой гарантии.\n\n2. Требование бенефициара должно быть представлено гаранту до окончания срока действия независимой гарантии.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 374. Представление требования по независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8abf231cf6be5bc356421654b41cb37219af1b34c765d76f7754fb1647cd9d65"},{"code_id":"GK_RF","article_number":"375.1","version_date":"1994-11-30","article_text":"Бенефициар обязан возместить гаранту или принципалу убытки, которые причинены вследствие того, что представленные им документы являлись недостоверными либо предъявленное требование являлось необоснованным.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 375.1. Ответственность бенефициара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e8b32cf19abb4817fc2544401824a5c8047b804ccaf0dd2e33105b19bf84ea56"},{"code_id":"GK_RF","article_number":"376","version_date":"1994-11-30","article_text":"1. Гарант отказывает бенефициару в удовлетворении его требования, если это требование или приложенные к нему документы не соответствуют условиям независимой гарантии либо представлены гаранту по окончании срока действия независимой гарантии. Гарант должен уведомить об этом бенефициара в срок, предусмотренный пунктом 2 статьи 375 настоящего Кодекса, указав причину отказа.\n\n2. Гарант имеет право приостановить платеж на срок до семи дней, если он имеет разумные основания полагать, что:\n\n1) какой-либо из представленных ему документов является недостоверным;\n\n2) обстоятельство, на случай возникновения которого независимая гарантия обеспечивала интересы бенефициара, не возникло;\n\n3) основное обязательство принципала, обеспеченное независимой гарантией, недействительно;\n\n4) исполнение по основному обязательству принципала принято бенефициаром без каких-либо возражений.\n\n3. В случае приостановления платежа гарант обязан уведомить бенефициара и принципала о причинах и сроке приостановления платежа незамедлительно.\n\n4. Гарант несет ответственность перед бенефициаром и принципалом за необоснованное приостановление платежа.\n\n5. По истечении срока, предусмотренного пунктом 2 настоящей статьи, при отсутствии оснований для отказа в удовлетворении требования бенефициара (пункт 1 настоящей статьи) гарант обязан произвести платеж по гарантии.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 376. Отказ гаранта удовлетворить требование бенефициара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b06f970751f521d04be9c7d9fd53c0790336d7c06726612274e835be5cef59b3"},{"code_id":"GK_RF","article_number":"378","version_date":"1994-11-30","article_text":"1. Обязательство гаранта перед бенефициаром по независимой гарантии прекращается:\n\n1) уплатой бенефициару суммы, на которую выдана независимая гарантия;\n\n2) окончанием определенного в независимой гарантии срока, на который она выдана;\n\n3) вследствие отказа бенефициара от своих прав по гарантии;\n\n4) по соглашению гаранта с бенефициаром о прекращении этого обязательства.\n\n2. Независимой гарантией или соглашением гаранта с бенефициаром может быть предусмотрено, что для прекращения обязательства гаранта перед бенефициаром необходимо возвратить гаранту выданную им гарантию.\n\nПрекращение обязательства гаранта по основаниям, указанным в подпунктах 1 и 2 пункта 1 настоящей статьи, не зависит от того, возвращена ли ему независимая гарантия.\n\n3. Гарант, которому стало известно о прекращении независимой гарантии по основаниям, предусмотренным настоящей статьей, должен уведомить об этом принципала без промедления.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 378. Прекращение независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ddd8b00818e9f1ab91e57a5e927acbd07f04f7f15e92c94cde4816540d4c49c"},{"code_id":"GK_RF","article_number":"379","version_date":"1994-11-30","article_text":"1. Принципал обязан возместить гаранту выплаченные в соответствии с условиями независимой гарантии денежные суммы, если соглашением о выдаче гарантии не предусмотрено иное.\n\n2. Гарант не вправе требовать от принципала возмещения денежных сумм, уплаченных бенефициару не в соответствии с условиями независимой гарантии или за нарушение обязательства гаранта перед бенефициаром, за исключением случаев, если соглашением гаранта с принципалом предусмотрено иное либо принципал дал согласие на платеж по гарантии.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 379. Возмещение гаранту сумм, выплаченных по независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d56d970ac3733b7297621e0906a18a69da8de4384fb59a1a35b035798e1c430f"},{"code_id":"GK_RF","article_number":"38","version_date":"1994-11-30","article_text":"1. При необходимости постоянного управления недвижимым и ценным движимым имуществом подопечного орган опеки и попечительства заключает с управляющим, определенным этим органом, договор о доверительном управлении таким имуществом. В этом случае опекун или попечитель сохраняет свои полномочия в отношении того имущества подопечного, которое не передано в доверительное управление.\n\nПри осуществлении управляющим правомочий по управлению имуществом подопечного на управляющего распространяется действие правил, предусмотренных пунктами 2 и 3 статьи 37 настоящего Кодекса.\n\n2. Доверительное управление имуществом подопечного прекращается по основаниям, предусмотренным законом для прекращения договора о доверительном управлении имуществом, а также в случаях прекращения опеки и попечительства.","article_title":"Статья 38. Доверительное управление имуществом подопечного","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36ae01a539f7fd1d3e005021c10cd7738d793c33aca6b5114e4f391e32554ad0"},{"code_id":"GK_RF","article_number":"380","version_date":"1994-11-30","article_text":"1. Задатком признается денежная сумма, выдаваемая одной из договаривающихся сторон в счет причитающихся с нее по договору платежей другой стороне, в доказательство заключения договора и в обеспечение его исполнения.\n\n2. Соглашение о задатке независимо от суммы задатка должно быть совершено в письменной форме.\n\n3. В случае сомнения в отношении того, является ли сумма, уплаченная в счет причитающихся со стороны по договору платежей, задатком, в частности вследствие несоблюдения правила, установленного пунктом 2 настоящей статьи, эта сумма считается уплаченной в качестве аванса, если не доказано иное.","article_title":"Статья 380. Понятие задатка. Форма соглашения о задатке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78f25abc9a5347a2e53b20fc72a234bf8505fd2233884bacb1d9aa67e9839135"},{"code_id":"GK_RF","article_number":"381","version_date":"1994-11-30","article_text":"1. При прекращении обязательства до начала его исполнения по соглашению сторон либо вследствие невозможности исполнения (статья 416) задаток должен быть возвращен.\n\n2. Если за неисполнение договора ответственна сторона, давшая задаток, он остается у другой стороны. Если за неисполнение договора ответственна сторона, получившая задаток, она обязана уплатить другой стороне двойную сумму задатка.\n\nСверх того, сторона, ответственная за неисполнение договора, обязана возместить другой стороне убытки с зачетом суммы задатка, если в договоре не предусмотрено иное.\n\n(Дополнение параграфом - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 381. Последствия прекращения и неисполнения обязательства, обеспеченного задатком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f70de94d35de2e883a2ba71754315eb60b97cc34e724b1211ebd0cbc39afe8f6"}]$law7v009$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
